window.OPUS_PAGES["011"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Herbarium Imaginarium — A Cabinet of Plants That Never Were</title>\n<meta name=\"description\" content=\"A Victorian botanical specimen cabinet of imaginary plants, each grown by a branching grammar, drawn in sepia ink, strapped with paper tape and labelled with an invented Latin binomial.\">\n<style>\n:root{\n  --paper:#efe6d2;\n  --sheet:#f6efdd;\n  --ink:#4a3622;\n  --ink-soft:#6f5a3e;\n  --ink-faint:rgba(74,54,34,.55);\n  --green:#6b7f4e;\n  --green-pale:#9aa77a;\n  --madder:#9e2f28;\n  --madder-soft:#b85a4c;\n  --brass-hi:#e2c682;\n  --brass-lo:#7a5a24;\n  --serif:\"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"P052\",\"Book Antiqua\",Georgia,serif;\n  --panel-w:clamp(300px,26vw,390px);\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{\n  margin:0;min-height:100vh;color:var(--ink);font-family:var(--serif);\n  background-color:var(--paper);\n  background-image:var(--fibre,none),repeating-linear-gradient(93deg,rgba(255,255,255,.035) 0 1px,transparent 1px 5px),repeating-linear-gradient(3deg,rgba(120,90,50,.025) 0 1px,transparent 1px 7px);\n  background-size:320px 320px,auto,auto;\n}\n/* foxing and age toning, fixed to the viewport so the whole cabinet feels old */\nbody::before{\n  content:\"\";position:fixed;inset:0;z-index:-1;pointer-events:none;\n  background:\n    radial-gradient(circle at 7% 12%,rgba(150,96,44,.22) 0 2px,rgba(150,96,44,.09) 5px,transparent 13px),\n    radial-gradient(circle at 11% 16%,rgba(150,96,44,.14) 0 1px,rgba(150,96,44,.05) 3px,transparent 7px),\n    radial-gradient(circle at 23% 83%,rgba(140,88,40,.20) 0 3px,rgba(140,88,40,.07) 8px,transparent 18px),\n    radial-gradient(circle at 26% 88%,rgba(140,88,40,.12) 0 1px,transparent 6px),\n    radial-gradient(circle at 44% 6%,rgba(160,104,50,.16) 0 2px,rgba(160,104,50,.05) 6px,transparent 14px),\n    radial-gradient(circle at 63% 94%,rgba(150,96,44,.18) 0 2px,rgba(150,96,44,.06) 7px,transparent 16px),\n    radial-gradient(circle at 78% 9%,rgba(140,90,42,.14) 0 3px,rgba(140,90,42,.05) 9px,transparent 20px),\n    radial-gradient(circle at 91% 37%,rgba(150,96,44,.20) 0 2px,rgba(150,96,44,.07) 6px,transparent 15px),\n    radial-gradient(circle at 94% 41%,rgba(150,96,44,.10) 0 1px,transparent 5px),\n    radial-gradient(circle at 86% 78%,rgba(130,84,38,.16) 0 4px,rgba(130,84,38,.05) 10px,transparent 22px),\n    radial-gradient(circle at 52% 58%,rgba(150,96,44,.08) 0 2px,transparent 9px),\n    radial-gradient(circle at 34% 41%,rgba(150,96,44,.07) 0 3px,transparent 12px),\n    radial-gradient(ellipse 60% 40% at 0% 100%,rgba(150,108,52,.16),transparent 70%),\n    radial-gradient(ellipse 50% 35% at 100% 0%,rgba(150,108,52,.13),transparent 70%),\n    radial-gradient(ellipse 120% 95% at 50% 45%,transparent 58%,rgba(116,80,36,.24) 100%);\n}\n::selection{background:rgba(158,47,40,.22)}\na{color:inherit}\n.skip{position:absolute;left:-999px;top:8px;background:var(--ink);color:var(--sheet);padding:8px 14px;z-index:99}\n.skip:focus{left:8px}\n:focus-visible{outline:2px solid var(--madder);outline-offset:4px}\n\n/* ---------- layout ---------- */\n.page{display:grid;grid-template-columns:var(--panel-w) minmax(0,1fr);min-height:100vh}\n.index-panel{\n  position:sticky;top:0;height:100vh;overflow:auto;padding:34px 30px 30px 38px;\n  border-right:1px solid rgba(74,54,34,.28);\n  box-shadow:inset -5px 0 0 -4px rgba(74,54,34,.18),6px 0 22px -18px rgba(74,54,34,.5);\n  scrollbar-width:thin;scrollbar-color:rgba(74,54,34,.3) transparent;\n}\n.cabinet{padding:32px clamp(18px,3vw,46px) 56px;min-width:0}\n\n/* brass label holder, like the front of a specimen drawer */\n.holder{\n  display:inline-flex;position:relative;padding:6px 22px;border-radius:4px;\n  background:linear-gradient(160deg,var(--brass-hi) 0%,#b8944c 30%,var(--brass-lo) 52%,#c9a860 70%,#8a6a2e 100%);\n  box-shadow:0 1px 0 rgba(255,255,255,.5) inset,0 -1px 0 rgba(0,0,0,.25) inset,0 3px 6px -2px rgba(60,40,15,.55);\n}\n.holder::before,.holder::after{\n  content:\"\";position:absolute;top:50%;width:7px;height:7px;margin-top:-3.5px;border-radius:50%;\n  background:radial-gradient(circle at 35% 35%,#f4dea0,#9a7632 55%,#5a4218);\n  box-shadow:0 1px 1px rgba(0,0,0,.4);\n}\n.holder::before{left:7px}.holder::after{right:7px}\n.holder span{\n  display:block;padding:5px 14px 4px;background:#f4ecd8;color:var(--ink);font-size:12.5px;letter-spacing:.2em;\n  font-variant:small-caps;text-transform:lowercase;box-shadow:inset 0 1px 3px rgba(74,54,34,.35);white-space:nowrap;\n}\nh1{margin:26px 0 0;font-weight:400;line-height:.92;font-size:clamp(42px,3.75vw,62px);letter-spacing:.005em}\nh1 .l1{display:block}\nh1 .l2{display:block;font-style:italic;padding-left:.32em;color:#3f2c19}\n.subtitle{margin:12px 0 0;font-size:13px;letter-spacing:.24em;font-variant:small-caps;text-transform:lowercase;color:var(--ink-soft)}\n.orn{display:block;width:100%;max-width:300px;height:22px;margin:16px 0 14px;color:var(--ink)}\n.intro{margin:0;font-size:15.5px;line-height:1.55;color:#4f3b26;hyphens:auto}\n.intro::first-letter{float:left;font-size:3.1em;line-height:.82;padding:4px 7px 0 0;color:var(--madder);font-style:italic}\n\n.actions{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0 20px}\n.btn{\n  -webkit-appearance:none;appearance:none;font:inherit;font-size:15px;line-height:1;display:inline-flex;align-items:center;gap:10px;\n  padding:12px 16px 11px 13px;border:1px solid var(--ink);color:var(--ink);background:#f7f0de;cursor:pointer;border-radius:1px;\n  box-shadow:inset 0 0 0 2px #f7f0de,inset 0 0 0 3px rgba(74,54,34,.35),0 2px 0 rgba(74,54,34,.25);\n  transition:transform .2s ease,box-shadow .2s ease,background-color .3s ease,color .3s ease;\n}\n.btn svg{width:20px;height:20px;flex:none}\n.btn:hover{transform:translateY(-1px);box-shadow:inset 0 0 0 2px #f7f0de,inset 0 0 0 3px rgba(74,54,34,.45),0 4px 8px -3px rgba(74,54,34,.45)}\n.btn:active{transform:translateY(1px);box-shadow:inset 0 0 0 2px #f7f0de,inset 0 0 0 3px rgba(74,54,34,.45),0 0 0 rgba(74,54,34,.25)}\n.btn-primary{background:var(--ink);color:#f6edd8;box-shadow:inset 0 0 0 2px var(--ink),inset 0 0 0 3px rgba(246,237,216,.4),0 2px 0 rgba(40,28,14,.4)}\n.btn-primary:hover{background:#3d2c1b;box-shadow:inset 0 0 0 2px #3d2c1b,inset 0 0 0 3px rgba(246,237,216,.55),0 5px 10px -4px rgba(40,28,14,.6)}\n.btn-primary:active{box-shadow:inset 0 0 0 2px var(--ink),inset 0 0 0 3px rgba(246,237,216,.4)}\n.btn[aria-pressed=\"true\"]{background:#e6dcc2;box-shadow:inset 0 2px 5px rgba(74,54,34,.35),inset 0 0 0 3px rgba(74,54,34,.25)}\n.btn .kbd{font-size:11px;opacity:.6;letter-spacing:.08em;margin-left:2px;font-style:italic}\n\n.ledger{margin:0 0 20px;padding:0;list-style:none;font-size:14px}\n.ledger li{display:flex;align-items:baseline;gap:6px;padding:4px 0}\n.ledger li::after{content:\"\";order:1;flex:1;border-bottom:1px dotted rgba(74,54,34,.45);transform:translateY(-3px)}\n.ledger .v{order:2;font-style:italic;color:var(--madder);font-variant-numeric:oldstyle-nums}\n.ledger .k{font-variant:small-caps;text-transform:lowercase;letter-spacing:.08em}\n\n.index-title{margin:4px 0 8px;font-size:12px;font-weight:400;letter-spacing:.24em;font-variant:small-caps;text-transform:lowercase;color:var(--ink-soft);display:flex;align-items:center;gap:10px}\n.index-title::after{content:\"\";flex:1;height:1px;background:linear-gradient(90deg,rgba(74,54,34,.45),transparent)}\n.index{list-style:none;margin:0 0 22px;padding:0}\n.index li{border-bottom:1px solid rgba(74,54,34,.12)}\n.index button{\n  -webkit-appearance:none;appearance:none;width:100%;display:flex;align-items:baseline;gap:10px;background:none;border:0;padding:7px 2px;\n  font:inherit;font-size:15px;color:var(--ink);text-align:left;cursor:pointer;transition:color .2s,padding-left .25s;\n}\n.index button:hover{color:var(--madder);padding-left:8px}\n.index .ix-no{font-size:11.5px;letter-spacing:.08em;color:var(--ink-soft);font-variant-numeric:tabular-nums;min-width:40px}\n.index i{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.index li.fresh{animation:inkin 1.4s ease}\n@keyframes inkin{from{background:rgba(158,47,40,.14)}to{background:transparent}}\n.footnote{margin:0;font-size:12.5px;line-height:1.55;color:var(--ink-soft);font-style:italic}\n.footnote kbd{font-family:inherit;font-style:normal;font-size:11px;border:1px solid rgba(74,54,34,.4);border-bottom-width:2px;padding:0 5px;border-radius:2px;background:rgba(255,255,255,.35)}\n\n/* ---------- the cabinet grid ---------- */\n.drawer-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:0 auto 18px;max-width:var(--grid-max);font-size:12.5px;letter-spacing:.2em;font-variant:small-caps;text-transform:lowercase;color:var(--ink-soft)}\n.drawer-head b{font-weight:400;color:var(--ink)}\n.grid{\n  --grid-max:max(760px,calc((100vh - 170px) / 2 / 1.4 * 3 + 64px));\n  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px 32px;max-width:var(--grid-max);margin:0 auto;list-style:none;padding:0;\n}\n.cabinet{--grid-max:max(760px,calc((100vh - 170px) / 2 / 1.4 * 3 + 64px))}\n.card{position:relative;margin:0;transform:rotate(var(--rot,0deg));transition:transform .55s cubic-bezier(.2,.8,.2,1)}\n.card:hover,.card:focus-within{transform:rotate(0deg) translateY(-5px)}\n.sheet{\n  position:relative;width:100%;aspect-ratio:600/840;background-color:var(--sheet);\n  background-image:var(--fox,none);\n  box-shadow:inset 0 0 38px rgba(160,118,60,.16),inset 0 0 2px rgba(120,90,50,.35),0 1px 1px rgba(74,54,34,.25),0 10px 22px -12px rgba(60,40,20,.55);\n  transition:box-shadow .6s ease;\n}\n.sheet::before{content:\"\";position:absolute;inset:0;pointer-events:none;background-image:var(--fibre,none);background-size:320px 320px;opacity:.9}\n.card:hover .sheet{box-shadow:inset 0 0 38px rgba(160,118,60,.16),inset 0 0 2px rgba(120,90,50,.35),0 2px 3px rgba(74,54,34,.2),0 22px 34px -16px rgba(60,40,20,.6)}\n.sheet svg{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible}\n.sheet .plant{\n  filter:drop-shadow(.5px 1.2px .7px rgba(58,38,18,.38)) saturate(1) sepia(0) contrast(1) brightness(1);\n  transition:filter 1.1s ease,opacity 1.1s ease;\n}\n.furn text{font-family:var(--serif);fill:var(--ink)}\n.furn .t-caps{font-size:11px;letter-spacing:2.4px}\n.furn .t-name{font-style:italic}\n.furn .t-sm{font-size:12.5px;fill:#5a4630}\n.furn .t-hand{font-size:14px;font-style:italic;fill:#3e2c1a}\n.furn .t-stamp{font-size:10.5px;letter-spacing:1.4px;fill:var(--madder);font-weight:700}\n.furn .t-slip{font-size:11.5px;font-style:italic;fill:#4d3a26}\n.card figcaption{margin-top:11px;display:flex;align-items:baseline;justify-content:center;gap:9px;font-size:14.5px;white-space:nowrap;min-width:0}\n.card figcaption .no{font-size:11px;letter-spacing:.14em;color:var(--ink-soft);font-variant-numeric:tabular-nums;flex:none}\n.card figcaption i{overflow:hidden;text-overflow:ellipsis}\n.examine{\n  -webkit-appearance:none;appearance:none;position:absolute;left:0;top:0;width:100%;aspect-ratio:600/840;background:transparent;border:0;padding:0;margin:0;cursor:zoom-in;\n}\n.examine:focus-visible{outline-offset:6px}\n\n/* growth: stroke-by-stroke ink */\n.grow .st{stroke-dasharray:1 1;stroke-dashoffset:1;animation:ink var(--t,1s) linear var(--d,0s) forwards,vis .01s linear var(--d,0s) both}\n.grow .gl{transform:scale(0);animation:unfurl var(--u,.7s) cubic-bezier(.25,1.35,.5,1) var(--d,0s) forwards}\n.grow .gf{transform:scale(0) rotate(-50deg);animation:bloom var(--u,.9s) cubic-bezier(.2,1.25,.4,1) var(--d,0s) forwards}\n.grow .tape{opacity:0;transform:translate(-5px,-14px) rotate(-4deg);animation:tapeon .5s cubic-bezier(.2,.9,.3,1) var(--d,0s) forwards}\n.grow .ink-late{opacity:0;animation:fadein .9s ease var(--d,0s) forwards}\n.grow .stamp{opacity:0;transform:scale(1.35);animation:stampon .38s cubic-bezier(.3,1.6,.5,1) var(--d,0s) forwards}\n@keyframes ink{to{stroke-dashoffset:0}}\n@keyframes vis{from{visibility:hidden}to{visibility:visible}}\n@keyframes unfurl{to{transform:scale(1)}}\n@keyframes bloom{to{transform:scale(1) rotate(0deg)}}\n@keyframes tapeon{to{opacity:1;transform:none}}\n@keyframes fadein{to{opacity:1}}\n@keyframes stampon{to{opacity:1;transform:scale(1)}}\n.stamp{transform-box:fill-box;transform-origin:50% 50%}\n\n/* pressed */\n.is-pressed .sheet .plant{filter:drop-shadow(0 0 0 rgba(58,38,18,0)) saturate(.5) sepia(.72) contrast(.9) brightness(1.03);opacity:.8}\n.is-pressed .sheet{box-shadow:inset 0 0 38px rgba(160,118,60,.2),inset 0 0 0 9px rgba(120,90,50,.035),inset 0 0 2px rgba(120,90,50,.35),0 1px 1px rgba(74,54,34,.25),0 6px 14px -10px rgba(60,40,20,.5)}\n.pressing .card .sheet{animation:squash .7s cubic-bezier(.3,.7,.3,1)}\n@keyframes squash{0%{transform:none}30%{transform:scale(.982,.974);filter:brightness(.96)}100%{transform:none}}\n.enter{animation:laydown .8s cubic-bezier(.2,.8,.2,1) both}\n@keyframes laydown{from{opacity:0;transform:translateY(-26px) rotate(-3deg) scale(1.04)}to{opacity:1;transform:rotate(var(--rot,0deg))}}\n\n/* ---------- lightbox ---------- */\n.lb{\n  position:fixed;inset:0;z-index:50;overflow:auto;padding:28px 24px;display:flex;\n  background:radial-gradient(ellipse 80% 70% at 45% 45%,rgba(62,44,24,.9),rgba(22,14,7,.96));\n  opacity:0;transition:opacity .35s ease;overscroll-behavior:contain;\n}\n.lb[hidden]{display:none}\n.lb.open{opacity:1}\n.lb-inner{margin:auto;display:grid;grid-template-columns:auto minmax(280px,340px);gap:34px;align-items:center;position:relative;transform:translateY(12px) scale(.985);transition:transform .45s cubic-bezier(.2,.8,.2,1)}\n.lb.open .lb-inner{transform:none}\n.lb-stage{display:flex;flex-direction:column;align-items:center;gap:10px}\n.lb-sheet{position:relative;height:min(84vh,1000px);aspect-ratio:600/840;touch-action:none;cursor:zoom-in;box-shadow:0 30px 60px -20px rgba(0,0,0,.7)}\n.lb-sheet .sheet{position:absolute;inset:0;width:100%;height:100%}\n.lb-sheet.looking{cursor:none}\n.lb-hint{margin:0;font-size:12.5px;letter-spacing:.14em;color:rgba(240,228,204,.66);font-variant:small-caps;text-transform:lowercase;text-align:center}\n.lb-notes{\n  position:relative;padding:30px 28px 26px;color:var(--ink);\n  background-color:#f3ead4;\n  background-image:repeating-linear-gradient(180deg,transparent 0 27px,rgba(90,120,150,.16) 27px 28px),linear-gradient(90deg,transparent 30px,rgba(158,47,40,.28) 30px 31px,transparent 31px);\n  background-position:0 14px,0 0;\n  box-shadow:0 26px 50px -22px rgba(0,0,0,.75),inset 0 0 30px rgba(160,118,60,.18);\n}\n.lb-no{margin:0 0 4px 16px;font-size:12px;letter-spacing:.24em;font-variant:small-caps;text-transform:lowercase;color:var(--madder)}\n.lb-notes h2{margin:0 0 2px 16px;font-weight:400;font-size:29px;line-height:1.1}\n.lb-auth{display:block;font-style:normal;font-size:14px;letter-spacing:.06em;color:var(--ink-soft);margin-top:4px}\n.lb-vern{margin:4px 0 16px 16px;font-size:15px;color:var(--ink-soft)}\n.lb-notes dl{margin:0 0 14px 16px;display:grid;grid-template-columns:auto 1fr;gap:3px 14px;font-size:14px;line-height:1.5}\n.lb-notes dt{font-variant:small-caps;text-transform:lowercase;letter-spacing:.1em;color:var(--ink-soft)}\n.lb-notes dd{margin:0;font-style:italic}\n.lb-desc{margin:0 0 18px 16px;font-size:15px;line-height:1.62}\n.lb-nav{display:flex;flex-wrap:wrap;gap:10px;margin-left:16px}\n.lb-nav .btn{padding:10px 12px;font-size:14px}\n.lb-close{\n  -webkit-appearance:none;appearance:none;position:fixed;top:16px;right:18px;z-index:3;width:46px;height:46px;border-radius:50%;\n  border:1px solid rgba(240,228,204,.45);background:rgba(30,20,10,.55);color:#f3e7cc;font:inherit;font-size:26px;line-height:1;cursor:pointer;\n  display:grid;place-items:center;transition:transform .25s ease,background-color .25s ease;\n}\n.lb-close:hover{transform:rotate(90deg);background:rgba(158,47,40,.7)}\n\n/* the loupe */\n.loupe{\n  position:fixed;left:0;top:0;width:230px;height:230px;margin:-115px 0 0 -115px;z-index:70;pointer-events:none;border-radius:50%;\n  padding:8px;opacity:0;scale:.55;transition:opacity .18s ease,scale .28s cubic-bezier(.2,1.3,.4,1);\n  background:conic-gradient(from 30deg,#f3dc9c,#8f6b2a 18%,#d9b86a 36%,#6d4f1e 52%,#e8cd88 70%,#7d5d24 86%,#f3dc9c);\n  box-shadow:0 18px 36px -8px rgba(0,0,0,.6),0 0 0 1px rgba(60,40,15,.6);\n}\n.loupe.on{opacity:1;scale:1}\n.loupe::before{\n  content:\"\";position:absolute;left:50%;top:50%;width:22px;height:118px;margin-left:-11px;border-radius:9px 9px 11px 11px;\n  transform-origin:50% 0;transform:rotate(-45deg) translateY(116px);\n  background:linear-gradient(90deg,#2e1b0e,#6e4524 35%,#8a5a31 50%,#4a2d17 80%,#2a180c);\n  box-shadow:0 6px 12px rgba(0,0,0,.45);\n}\n.loupe-glass{position:relative;width:100%;height:100%;border-radius:50%;overflow:hidden;background:var(--sheet);box-shadow:inset 0 0 0 1px rgba(40,25,10,.5)}\n.loupe-glass::after{\n  content:\"\";position:absolute;inset:0;border-radius:50%;pointer-events:none;\n  background:radial-gradient(circle at 32% 26%,rgba(255,255,255,.34),rgba(255,255,255,0) 28%),radial-gradient(circle at 50% 50%,transparent 62%,rgba(40,24,8,.35) 100%);\n}\n.loupe-view{position:absolute;left:0;top:0;transform-origin:0 0}\n.loupe-view .sheet{position:absolute;left:0;top:0}\n\n/* ---------- responsive ---------- */\n@media (max-width:1100px){\n  .page{grid-template-columns:1fr}\n  .index-panel{position:relative;height:auto;overflow:visible;border-right:0;border-bottom:1px solid rgba(74,54,34,.28);box-shadow:0 6px 22px -18px rgba(74,54,34,.5);padding:30px clamp(18px,5vw,48px) 26px;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:0 44px}\n  .index-panel > .col-a{grid-column:1}\n  .index-panel > .col-b{grid-column:2;align-self:end}\n  .cabinet{--grid-max:980px}\n  .grid{--grid-max:980px}\n}\n@media (max-width:760px){\n  .index-panel{display:block;padding:26px 18px 22px}\n  .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 18px}\n  .index,.index-title{display:none}\n  .drawer-head{font-size:11px;letter-spacing:.14em}\n}\n@media (max-width:560px){ .footnote .keys{display:none} .btn .kbd{display:none} }\n@media (max-width:560px){\n  .grid{grid-template-columns:1fr;gap:34px}\n  .ledger{margin-bottom:14px}\n  .ledger li{padding:3px 0}\n  .cabinet{padding:26px 16px 48px}\n  h1{font-size:44px;margin-top:20px}\n  .intro{font-size:15px}\n  .actions{margin:18px 0 16px}\n  .btn{font-size:14.5px}\n  .card{max-width:420px;margin:0 auto;width:100%}\n}\n@media (max-width:900px){\n  .lb{padding:70px 16px 28px}\n  .lb-inner{grid-template-columns:1fr;gap:22px;width:100%;max-width:560px}\n  .lb-sheet{height:auto;width:100%}\n  .lb-notes{padding:24px 20px 22px}\n}\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  .card,.sheet,.sheet .plant,.lb,.lb-inner,.loupe{transition:none!important}\n  .grow .st,.grow .gl,.grow .gf,.grow .tape,.grow .ink-late,.grow .stamp,.enter,.pressing .card .sheet{animation:none!important;opacity:1;transform:none;stroke-dashoffset:0;visibility:visible}\n  .grow .st{stroke-dasharray:none}\n}\n</style>\n</head>\n<body>\n<a class=\"skip\" href=\"#cabinet\">Skip to the specimens</a>\n<div class=\"page\">\n  <header class=\"index-panel\" aria-label=\"Cabinet index\">\n    <div class=\"col-a\">\n      <div class=\"holder\"><span>Cabinet VII &middot; Drawer iii</span></div>\n      <h1><span class=\"l1\">Herbarium</span><span class=\"l2\">Imaginarium</span></h1>\n      <p class=\"subtitle\">Specimens of an unrecorded flora</p>\n      <svg class=\"orn\" viewBox=\"0 0 300 22\" aria-hidden=\"true\">\n        <g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\">\n          <path d=\"M4 11H112\" stroke-width=\".8\"/>\n          <path d=\"M188 11H296\" stroke-width=\".8\"/>\n          <path d=\"M8 14H104\" stroke-width=\".4\" opacity=\".6\"/>\n          <path d=\"M196 8H292\" stroke-width=\".4\" opacity=\".6\"/>\n          <path d=\"M118 11c7-8 15-8 22-2M182 11c-7-8-15-8-22-2\" stroke-width=\"1\"/>\n          <path d=\"M118 11c7 8 15 8 22 2M182 11c-7 8-15 8-22 2\" stroke-width=\".7\"/>\n          <path d=\"M131 7c-1-4 1-6 5-6M169 7c1-4-1-6-5-6\" stroke-width=\".7\"/>\n        </g>\n        <path d=\"M150 3l6 8-6 8-6-8z\" fill=\"#9e2f28\"/>\n        <circle cx=\"150\" cy=\"11\" r=\"1.6\" fill=\"#f6efdd\"/>\n        <circle cx=\"113\" cy=\"11\" r=\"1.8\" fill=\"currentColor\"/>\n        <circle cx=\"187\" cy=\"11\" r=\"1.8\" fill=\"currentColor\"/>\n      </svg>\n      <p class=\"intro\">Six sheets from a drawer of plants that never grew anywhere but here. Each is raised from a seed of numbers by a branching grammar, then pressed, strapped down with gummed tape and labelled in the manner of the old collectors.</p>\n      <div class=\"actions\">\n        <button type=\"button\" class=\"btn btn-primary\" id=\"collect\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21V9\"/><path d=\"M12 13c-4 0-6-2-7-6 4 0 6 2 7 6zM12 10c3 0 5-2 6-5-3 0-5 2-6 5z\"/><path d=\"M7 21h10\"/></g></svg>\n          Collect a new specimen <span class=\"kbd\">N</span>\n        </button>\n        <button type=\"button\" class=\"btn\" id=\"press\" aria-pressed=\"false\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"15\" width=\"18\" height=\"4\" rx=\".5\"/><rect x=\"3\" y=\"8\" width=\"18\" height=\"3\" rx=\".5\"/><path d=\"M6 8V3M18 8V3M4.5 3h3M16.5 3h3M6 19v2M18 19v2\"/><path d=\"M8 13.2c1.5-.9 3-.9 4 0s2.5.9 4 0\" stroke-width=\"1\"/></g></svg>\n          <span id=\"press-label\">Press the sheets</span> <span class=\"kbd\">P</span>\n        </button>\n      </div>\n    </div>\n    <div class=\"col-b\">\n      <ul class=\"ledger\" aria-label=\"Drawer ledger\">\n        <li><span class=\"k\">Sheets in this drawer</span><span class=\"v\" id=\"lg-count\">six</span></li>\n        <li><span class=\"k\">Collected this sitting</span><span class=\"v\" id=\"lg-new\">none yet</span></li>\n        <li><span class=\"k\">Last accession</span><span class=\"v\" id=\"lg-last\">&mdash;</span></li>\n      </ul>\n      <h2 class=\"index-title\">Index of the drawer</h2>\n      <ol class=\"index\" id=\"index\"></ol>\n      <p class=\"footnote\">Every plant, collector and locality here is imaginary. The Latin, at least, is honest: each epithet agrees in gender with its genus. <span class=\"keys\"><kbd>N</kbd> collect &middot; <kbd>P</kbd> press &middot; <kbd>&larr;</kbd><kbd>&rarr;</kbd> turn sheets &middot; <kbd>Esc</kbd> close</span></p>\n    </div>\n  </header>\n\n  <main class=\"cabinet\" id=\"cabinet\">\n    <p class=\"drawer-head\"><span>Flora Incognita &middot; <b>Series&nbsp;II</b></span><span id=\"drawer-note\">six sheets, freshly mounted</span></p>\n    <div class=\"grid\" id=\"grid\" role=\"list\" aria-label=\"Specimen sheets\"></div>\n  </main>\n</div>\n\n<div class=\"lb\" id=\"lb\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"lb-title\" hidden>\n  <button type=\"button\" class=\"lb-close\" id=\"lb-close\" aria-label=\"Close the specimen\">&times;</button>\n  <div class=\"lb-inner\">\n    <div class=\"lb-stage\">\n      <div class=\"lb-sheet\" id=\"lb-sheet\" role=\"img\" aria-label=\"Enlarged specimen sheet\"></div>\n      <p class=\"lb-hint\" id=\"lb-hint\">Hover to examine with the loupe &middot; drag on touch screens</p>\n    </div>\n    <aside class=\"lb-notes\" aria-label=\"Collector's notes\">\n      <p class=\"lb-no\" id=\"lb-no\"></p>\n      <h2 id=\"lb-title\"></h2>\n      <p class=\"lb-vern\" id=\"lb-vern\"></p>\n      <dl id=\"lb-data\"></dl>\n      <p class=\"lb-desc\" id=\"lb-desc\"></p>\n      <div class=\"lb-nav\">\n        <button type=\"button\" class=\"btn\" id=\"lb-prev\" aria-label=\"Previous specimen\">&larr; Previous</button>\n        <button type=\"button\" class=\"btn\" id=\"lb-next\" aria-label=\"Next specimen\">Next &rarr;</button>\n        <button type=\"button\" class=\"btn\" id=\"lb-press\" aria-pressed=\"false\">Press</button>\n      </div>\n    </aside>\n  </div>\n  <div class=\"loupe\" id=\"loupe\" aria-hidden=\"true\"><div class=\"loupe-glass\"><div class=\"loupe-view\" id=\"loupe-view\"></div></div></div>\n</div>\n\n<script>\n(() => {\n'use strict';\nconst DEG = Math.PI / 180;\nconst reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst $ = (s) => document.querySelector(s);\n\n/* ------------------------------------------------------------------\n   Paper fibre: a seamless procedural tile, drawn once on a canvas\n------------------------------------------------------------------ */\nfunction paperTile(){\n  try{\n    const S = 320, c = document.createElement('canvas');\n    c.width = S; c.height = S;\n    const g = c.getContext('2d');\n    let seed = 7;\n    const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };\n    const fibre = (x, y, a, l, col, lw) => {\n      for (let ox = -S; ox <= S; ox += S) for (let oy = -S; oy <= S; oy += S){\n        const x0 = x + ox, y0 = y + oy;\n        if (x0 < -40 || x0 > S + 40 || y0 < -40 || y0 > S + 40) continue;\n        g.beginPath();\n        g.moveTo(x0, y0);\n        const b = (rnd() - .5) * l * .5;\n        g.quadraticCurveTo(x0 + Math.cos(a) * l * .5 - Math.sin(a) * b, y0 + Math.sin(a) * l * .5 + Math.cos(a) * b, x0 + Math.cos(a) * l, y0 + Math.sin(a) * l);\n        g.strokeStyle = col; g.lineWidth = lw; g.stroke();\n      }\n    };\n    for (let i = 0; i < 950; i++){\n      const dark = rnd() < .55;\n      const col = dark ? `rgba(118,86,48,${(.04 + rnd() * .09).toFixed(3)})` : `rgba(255,251,238,${(.14 + rnd() * .26).toFixed(3)})`;\n      fibre(rnd() * S, rnd() * S, rnd() * Math.PI * 2, 5 + rnd() * 24, col, .35 + rnd() * .7);\n    }\n    for (let i = 0; i < 420; i++){\n      g.fillStyle = `rgba(96,64,30,${(.05 + rnd() * .14).toFixed(3)})`;\n      g.beginPath(); g.arc(rnd() * S, rnd() * S, .25 + rnd() * .9, 0, Math.PI * 2); g.fill();\n    }\n    document.documentElement.style.setProperty('--fibre', 'url(\"' + c.toDataURL('image/png') + '\")');\n  }catch(e){ /* the paper is plain without it */ }\n}\npaperTile();\n\n/* ------------------------------------------------------------------\n   Seeded randomness\n------------------------------------------------------------------ */\nfunction rngFrom(seed){\n  let a = seed >>> 0;\n  return function(){\n    a = (a + 0x6D2B79F5) >>> 0;\n    let t = a;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\nfunction tools(r){\n  return {\n    r,\n    f: (a, b) => a + (b - a) * r(),\n    i: (a, b) => Math.floor(a + (b - a + 1) * r()),\n    pick: (arr) => arr[Math.floor(r() * arr.length)],\n    ch: (p) => r() < p,\n    sg: () => (r() < .5 ? -1 : 1)\n  };\n}\nconst clamp = (v, a, b) => Math.max(a, Math.min(b, v));\nconst n1 = (v) => Math.round(v * 10) / 10;\nfunction hex2rgb(h){ const n = parseInt(h.slice(1), 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }\nfunction mix(a, b, t){\n  const A = hex2rgb(a), B = hex2rgb(b);\n  return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('');\n}\n\n/* ------------------------------------------------------------------\n   Names: Latin binomials that agree in gender\n------------------------------------------------------------------ */\nconst STEMS = ['Vesper','Lumin','Chrys','Melan','Phyll','Astr','Noct','Silen','Umbr','Thalass','Or','Call','Myri','Dry','Lept','Chlor','Xanth','Eury','Argyr','Crypt','Selen','Hesper','Oneir','Mnem','Cirr','Glauc','Somn','Lachn','Nephel','Scot'];\nconst SUFFIXES = [['anthus','m'],['carpus','m'],['cladus','m'],['thamnus','m'],['dendron','n'],['phyllum','n'],['caulon','n'],['petalum','n'],['ella','f'],['aria','f'],['opsis','f'],['ago','f'],['stachys','f'],['odora','f']];\nconst REAL = new Set(['Phyllanthus','Nephelium','Chlorella','Glaucium','Cryptocarpus','Xanthium','Melanthium','Chrysopsis','Leptopetalum','Scotanthus','Astranthus','Callianthus','Dryandra','Chrysophyllum','Chrysanthus','Melanthus','Myriophyllum','Leptocarpus','Callopsis','Dryopsis','Chloranthus','Xanthella','Callistachys','Leptostachys','Myriocarpus','Orcaria','Astraria','Scotaria','Xanthophyllum','Chlorophyllum','Leptocladus','Melanocarpus','Glaucopsis','Umbraria','Thalassodendron','Eurycarpus','Oranthus','Calladendron','Orago','Callago']);\nconst EPITHETS = [\n  ['vagabund','12'],['lucifug','12'],['noctiflor','12'],['argente','12'],['plumos','12'],['pallid','12'],['umbros','12'],['pendul','12'],['ignot','12'],['tremul','12'],['chimaeric','12'],['obscur','12'],['nebulos','12'],['stellat','12'],['velutin','12'],['oblivios','12'],['imaginari','12'],['somnolent','12'],\n  ['mirabil','3'],['crepuscular','3'],['memorial','3'],['volubil','3'],['nocturnal','3'],['insomn','3'],['lunar','3'],['fragil','3'],\n  ['somnians','x'],['errans','x'],['evanescens','x'],['susurrans','x'],['vigilans','x'],['dormiens','x'],['fugax','x'],['recondens','x']\n];\nconst END = { '12': {m:'us', f:'a', n:'um'}, '3': {m:'is', f:'is', n:'e'} };\nconst FAMILIES = ['Somniaceae','Umbraceae','Chimaeraceae','Oneiraceae','Lucifugaceae','Fictaceae','Mnemosynaceae','Crepusculaceae','Nepheliaceae'];\nconst AUTHORS = ['Thistlew.','Fernsby','Marrowby','Quillf.','Ashgr.','Hollowbr.','Thistlew. & Fernsby'];\nconst COLLECTORS = ['A. Thistlewood','Rev. O. Fernsby','Prof. O. Marrowby','Capt. H. Quillfeather','Miss E. Ashgrove','Dr. P. Hollowbrook','Mrs. W. Lanternby'];\nconst LOCALITIES = ['Banks of the Nevermere','Lantern Falls, lower pool','Hedgerow, Wolds-under-Hollow',\"Chalk, St Ninnian's Reach\",'Peat by Glimmering Tarn','Moss-slope, Isle of Umbrel','Ruined orangery, Hushbury','Scree below Mt Quietude','Salt-marsh, Cape Seldom','Churchyard wall, Little Nowhere','Beech-hanger, Owlpenny Combe','Ditch by the Moth Inn'];\nconst ROMAN = ['i','ii','iii','iv','v','vi','vii','viii','ix','x','xi','xii'];\nconst VERN_A = [\"Lamplighter's\",\"Curate's\",\"Sexton's\",\"Widow's\",\"Clockmaker's\",\"Moth\",\"Midsummer\",\"Ink\",\"Candle\",\"Hollow\",\"Lantern\",\"Owl\",\"Dusk\",\"Ghost\",\"Silver\",\"Sleeper's\"];\nconst VERN_B = {\n  spicata: ['Bell','Bellwort','Spire','Foxbell','Taper'],\n  ramosa: ['Thorn','Bramble','Myrtle','Berry','Broom'],\n  umbella: ['Lace','Parsley','Umbrella','Hemlock-lace','Chervil'],\n  filix: ['Fern','Brake','Spleenwort','Maidenhair','Bracken'],\n  scandens: ['Vine','Bine','Creeper','Bryony','Tangle'],\n  rosula: ['Clock','Star','Cup','Rosette','Daisy']\n};\nconst WHIMSY = [\n  'Opens its flowers only while someone nearby is reading aloud.',\n  'Turns its leaves toward candlelight and ignores the sun entirely.',\n  'Smells faintly of pencil shavings and warm rain.',\n  'The collector swore it hummed a little as it was pressed.',\n  'In still air its seeds are said to fall upward.',\n  'First found growing in the gutter of an unfinished letter.',\n  'Closes at once at the mention of arithmetic.',\n  'Frequent in the margins of old atlases; rare elsewhere.',\n  'Keeps its dew until noon, then gives it back.',\n  'Village children call it lucky and will not say why.',\n  'Blooms on the one evening each year the clocks disagree.',\n  'Leaves rustle in rooms where no window is open.',\n  'Moths visit it in single file.',\n  'Grows only where a promise was once kept.'\n];\nfunction makeName(R){\n  let genus = '', gender = 'f', tries = 0;\n  do {\n    const stem = R.pick(STEMS), suf = R.pick(SUFFIXES);\n    const vowelEnd = /[aeiouy]$/.test(stem), vowelStart = /^[aeiouy]/.test(suf[0]);\n    genus = stem + (!vowelEnd && !vowelStart ? 'o' : '') + suf[0];\n    gender = suf[1];\n  } while (REAL.has(genus) && ++tries < 20);\n  const e = R.pick(EPITHETS);\n  const epithet = e[1] === 'x' ? e[0] : e[0] + END[e[1]][gender];\n  return { genus, epithet };\n}\n\n/* ------------------------------------------------------------------\n   A small parametric L-system\n------------------------------------------------------------------ */\nconst PU = { s: '[' }, PO = { s: ']' };\nconst F = (l, w) => ({ s: 'F', l, w: w == null ? 1 : w });\nconst T = (a) => ({ s: '+', a });\nconst Lf = (sz, o) => Object.assign({ s: 'L', sz }, o || {});\nconst K = (sz, o) => Object.assign({ s: 'K', sz }, o || {});\nconst Bd = (sz) => ({ s: 'B', sz });\nconst Ry = (sz) => ({ s: 'R', sz });\nconst Hd = (sz) => ({ s: 'H', sz });\nconst M = (s, o) => Object.assign({ s }, o || {});\n\nfunction derive(axiom, rules, n, finals){\n  let cur = axiom;\n  for (let i = 0; i < n; i++){\n    let changed = false;\n    const next = [];\n    for (const m of cur){\n      const rule = rules[m.s];\n      if (rule){ changed = true; const rep = rule(m, i); for (const x of rep) next.push(x); }\n      else next.push(m);\n    }\n    cur = next;\n    if (!changed) break;\n  }\n  const out = [];\n  for (const m of cur){\n    if (finals && finals[m.s]){ for (const x of finals[m.s](m)) out.push(x); }\n    else if (!rules[m.s]) out.push(m);\n  }\n  return out;\n}\n\nfunction interpret(mods, P, R){\n  const g = { segs: [], leaves: [], flowers: [], buds: [], berries: [], heads: [] };\n  let st = { x: 0, y: 0, h: 90 + P.lean, w: P.w0, d: 0, dep: 0 };\n  const stack = [];\n  for (const m of mods){\n    switch (m.s){\n      case 'F': {\n        let h = st.h + (R.r() * 2 - 1) * P.jit;\n        if (P.trop) h += P.trop.e * Math.sin((P.trop.t - h) * DEG);\n        const len = m.l, a = h * DEG;\n        const x2 = st.x + Math.cos(a) * len, y2 = st.y + Math.sin(a) * len;\n        const b = (R.r() * 2 - 1) * P.curl * len, pa = a + Math.PI / 2;\n        const cx = (st.x + x2) / 2 + Math.cos(pa) * b, cy = (st.y + y2) / 2 + Math.sin(pa) * b;\n        g.segs.push({ x1: st.x, y1: st.y, cx, cy, x2, y2, w: st.w * m.w, d0: st.d, len, dep: st.dep, h });\n        st.x = x2; st.y = y2; st.h = h; st.d += len; st.w *= P.taper;\n        break;\n      }\n      case '+': st.h += m.a + (R.r() * 2 - 1) * P.angJit; break;\n      case '[': stack.push(st); st = Object.assign({}, st, { dep: st.dep + 1, w: st.w * P.branchW }); break;\n      case ']': st = stack.pop() || st; break;\n      case 'L': g.leaves.push({ x: st.x, y: st.y, h: st.h, sz: m.sz, d: st.d, shape: m.shape || P.leafShape, pin: !!m.pin, sori: !!m.sori }); break;\n      case 'K': g.flowers.push({ x: st.x, y: st.y, h: st.h, sz: m.sz, d: st.d, type: m.type || P.flowerType }); break;\n      case 'B': g.buds.push({ x: st.x, y: st.y, h: st.h, sz: m.sz, d: st.d }); break;\n      case 'R': g.berries.push({ x: st.x, y: st.y, h: st.h, sz: m.sz, d: st.d }); break;\n      case 'H': g.heads.push({ x: st.x, y: st.y, h: st.h, sz: m.sz, d: st.d }); break;\n    }\n  }\n  return g;\n}\n\n/* ------------------------------------------------------------------\n   Six habits of growth\n------------------------------------------------------------------ */\nconst HABITS = ['spicata','ramosa','umbella','filix','scandens','rosula'];\nconst HABIT_TEXT = {\n  spicata: 'Erect herb; flowers borne in a single terminal spike',\n  ramosa: 'Much-branched undershrub, forking at every node',\n  umbella: 'Stout umbellifer; compound umbels of minute florets',\n  filix: 'Fern; fronds pinnate, the young ones coiled as croziers',\n  scandens: 'Scandent climber with coiling tendrils',\n  rosula: 'Acaulescent rosette; flowers on leafless scapes'\n};\nconst FLOWER_PALETTES = [\n  { petal: '#b4473c', edge: '#7a261f', centre: '#d8b25a', name: 'madder red' },\n  { petal: '#d38a7c', edge: '#9a4538', centre: '#8a5a2a', name: 'faded rose-madder' },\n  { petal: '#d9b95e', edge: '#94731f', centre: '#7a4a22', name: 'weld yellow' },\n  { petal: '#efe3c3', edge: '#96825c', centre: '#c79a40', name: 'cream' },\n  { petal: '#948aac', edge: '#5a4f70', centre: '#d8b25a', name: 'faded violet' },\n  { petal: '#8199ae', edge: '#4c6075', centre: '#e0c070', name: 'woad blue' }\n];\n\nfunction buildSpecies(seed, habit){\n  const R = tools(rngFrom(seed));\n  const P = { habit, jit: 3.5, angJit: 5, taper: .968, branchW: .7, curl: .1, lean: R.f(-5, 5), w0: 1, trop: null, wUnit: 4.4,\n    leafShape: 'lanceolate', flowerType: 'star', petals: R.pick([4, 5, 5, 5, 6]), fcol: R.pick(FLOWER_PALETTES),\n    serr: 0, teeth: R.i(10, 16), curlLeaf: R.f(.02, .12), pet: R.f(.06, .22), wMul: R.f(.85, 1.15),\n    stem: '#5d5733', roots: 'fibrous', greenBias: R.f(0, 1), berry: R.pick(['#9e2f28', '#8a2520', '#a8352c']) };\n  let mods;\n  if (habit === 'spicata'){\n    const N = R.i(10, 13), fs = N - R.i(4, 6), ang = R.f(40, 58), l0 = R.f(.85, 1.05);\n    const opposite = R.ch(.3);\n    P.leafShape = R.pick(['lanceolate', 'ovate', 'lobed', 'cordate', 'lanceolate']);\n    const leafSz = (P.leafShape === 'lanceolate' ? R.f(1.6, 2.2) : R.f(1.15, 1.55)) * (opposite ? .85 : 1);\n    P.serr = P.leafShape === 'lanceolate' || P.leafShape === 'ovate' ? (R.ch(.6) ? R.f(.1, .22) : 0) : 0;\n    P.flowerType = R.ch(.6) ? 'bell' : 'star';\n    if (P.flowerType === 'bell' && P.fcol.name === 'cream') P.fcol = FLOWER_PALETTES[4];\n    P.trop = { t: 90, e: 3 };\n    const rules = {\n      A: (m) => {\n        const k = m.k;\n        if (k >= N) return [F(.3, .8), Bd(.7)];\n        const f = 1 - k / N * .55, sg = k % 2 ? 1 : -1;\n        if (k < fs){\n          const sz = leafSz * (1 - k / N * .75) * R.f(.85, 1.1);\n          const out = [F(l0 * f * R.f(.85, 1.15))];\n          if (opposite) out.push(PU, T(ang), Lf(sz), PO, PU, T(-ang), Lf(sz), PO);\n          else out.push(PU, T(sg * ang), Lf(sz), PO);\n          if (k === 2 && R.ch(.55)) out.push(PU, T(-sg * R.f(24, 34)), M('A', { k: k + 3 }), PO);\n          out.push(M('A', { k: k + 1 }));\n          return out;\n        }\n        const out = [F(l0 * f * .55)];\n        const fz = (k - fs) / Math.max(1, N - fs);\n        out.push(PU, T(sg * R.f(48, 66)), F(.3, .35), K(R.f(.9, 1.1) * (1 - fz * .35)), PO);\n        if (R.ch(.35)) out.push(PU, T(-sg * R.f(40, 60)), F(.25, .35), Bd(.55), PO);\n        out.push(M('A', { k: k + 1 }));\n        return out;\n      }\n    };\n    const basal = [PU, T(78), Lf(leafSz * 1.05), PO, PU, T(-74), Lf(leafSz * .95), PO, PU, T(R.f(55, 65)), Lf(leafSz * .8), PO];\n    mods = derive(basal.concat([M('A', { k: 0 })]), rules, N + 5, { A: () => [Bd(.6)] });\n    P.roots = R.pick(['fibrous', 'taproot']);\n  } else if (habit === 'ramosa'){\n    const D = 4, baseA = R.f(22, 32);\n    P.leafShape = R.pick(['ovate', 'lanceolate', 'orbicular', 'spathulate', 'ovate']);\n    P.serr = R.ch(.3) ? R.f(.08, .16) : 0;\n    P.stem = '#6b4c2e'; P.wUnit = 5.6; P.taper = .95; P.branchW = .74; P.curl = .16;\n    P.trop = { t: 90, e: 2 };\n    const fruiting = R.ch(.65);\n    P.flowerType = 'star';\n    const leafy = (d) => (R.ch(.55) ? [PU, T(R.sg() * R.f(50, 75)), Lf(R.f(.45, .7) * Math.pow(.9, d)), PO] : []);\n    const rules = {\n      X: (m) => {\n        const d = m.d, l = Math.pow(.8, d) * R.f(.8, 1.2), a = baseA * R.f(.8, 1.25), v = R.r();\n        if (v < .4) return [F(l), ...leafy(d), PU, T(a), M('X', { d: d + 1 }), PO, F(l * .8), ...leafy(d), PU, T(-a), M('X', { d: d + 1 }), PO, T(a * .25), M('X', { d: d + 1 })];\n        if (v < .75) return [F(l), ...leafy(d), PU, T(-a), M('X', { d: d + 1 }), PO, F(l * .8), ...leafy(d), PU, T(a), M('X', { d: d + 1 }), PO, T(-a * .25), M('X', { d: d + 1 })];\n        return [F(l * 1.15), ...leafy(d), PU, T(a * .8), M('X', { d: d + 1 }), PO, PU, T(-a * .8), M('X', { d: d + 1 }), PO];\n      }\n    };\n    mods = derive([F(.8), F(.6), M('X', { d: 0 })], rules, D, {\n      X: () => {\n        const v = R.r();\n        if (v < .6) return [Lf(R.f(.5, .72))];\n        if (fruiting && v < .85) return [F(.12, .4), Ry(1)];\n        return [F(.1, .4), K(R.f(.32, .42))];\n      }\n    });\n    P.roots = 'woody';\n  } else if (habit === 'umbella'){\n    const N = R.i(4, 6), l0 = R.f(1.3, 1.6), rays = R.i(7, 11), spread = R.f(52, 72), rayLen = R.f(1.1, 1.5), leafSz = R.f(2.3, 3.1);\n    P.leafShape = R.pick(['pinnatifid', 'lobed', 'pinnatifid']);\n    P.wUnit = 5.8; P.taper = .97; P.branchW = .6;\n    P.fcol = R.ch(.7) ? FLOWER_PALETTES[3] : FLOWER_PALETTES[2];\n    P.flowerType = 'floret';\n    P.trop = { t: 90, e: 2.2 };\n    const rules = {\n      S: (m) => {\n        const k = m.k, sg = k % 2 ? 1 : -1;\n        if (k >= N) return [F(l0 * .55), M('U', { sc: 1 })];\n        const out = [F(l0 * R.f(.85, 1.1) * (1 - k * .06)), PU, T(sg * R.f(35, 55)), Lf(leafSz * (1 - k / N * .62)), PO];\n        if (k === N - 2 && R.ch(.75)) out.push(PU, T(-sg * R.f(28, 38)), F(l0 * .8, .8), F(l0 * .7), M('U', { sc: .6 }), PO);\n        out.push(M('S', { k: k + 1 }));\n        return out;\n      },\n      U: (m) => {\n        const out = [], n = m.sc < 1 ? Math.max(5, rays - 3) : rays;\n        for (let i = 0; i < n; i++){\n          const a = -spread + 2 * spread * i / (n - 1) + R.f(-4, 4);\n          out.push(PU, T(a), F(rayLen * m.sc * R.f(.9, 1.05) / Math.cos(a * DEG * .75), .32), M('V', { sc: m.sc }), PO);\n        }\n        return out;\n      },\n      V: (m) => {\n        const out = [], n = R.i(6, 9);\n        for (let j = 0; j < n; j++){\n          const b = -55 + 110 * j / (n - 1) + R.f(-5, 5);\n          out.push(PU, T(b), F(.26 * m.sc / Math.cos(b * DEG * .6), .22), K(.1), PO);\n        }\n        return out;\n      }\n    };\n    const basal = [PU, T(70), Lf(leafSz * 1.1), PO, PU, T(-72), Lf(leafSz * 1.05), PO];\n    mods = derive(basal.concat([M('S', { k: 0 })]), rules, N + 6, {});\n    P.roots = 'taproot';\n  } else if (habit === 'filix'){\n    P.leafShape = 'oblong'; P.stem = '#5b4a30'; P.wUnit = 3.8; P.taper = .975; P.branchW = .5; P.jit = 2; P.angJit = 3; P.curl = .05;\n    P.trop = { t: -90, e: R.f(1.2, 2.2) };\n    P.greenBias = R.f(.1, .5);\n    const fertile = R.ch(.7);\n    const frond = (N, l, pl) => {\n      const out = [];\n      for (let k = 0; k < N; k++){\n        const lk = l * (1 - k / N * .45);\n        if (k < 3){ out.push(F(lk)); continue; }\n        const q = Math.pow(Math.sin(Math.PI * (k - 1.4) / (N - 1.4)), .75);\n        const pLen = pl * Math.max(.18, q);\n        const pa = R.f(58, 70);\n        out.push(F(lk * .5), PU, T(pa), M('Q', { len: pLen, sg: 1 }), PO, F(lk * .5), PU, T(-pa), M('Q', { len: pLen, sg: -1 }), PO);\n      }\n      // crozier tip\n      for (let i = 0; i < 9; i++) out.push(T(22 + i * 5), F(.09 * (1 - i / 11), .6));\n      return out;\n    };\n    const rules = {\n      Q: (m) => {\n        const steps = Math.max(2, Math.round(m.len / .24)), out = [];\n        for (let j = 0; j < steps; j++){\n          const s = m.len / steps, psz = s * 1.05 * (1 - j / steps * .5);\n          out.push(F(s, .55), T(m.sg * 1.5), PU, T(64), Lf(psz, { sori: fertile && j < steps - 1 }), PO, PU, T(-64), Lf(psz, { sori: fertile && j < steps - 1 }), PO);\n        }\n        out.push(Lf(m.len / steps * 1.1));\n        return out;\n      }\n    };\n    const young = [];\n    for (let i = 0; i < 14; i++) young.push(F(.22 * (1 - i / 16), .7), T(-(14 + i * 6)));\n    const ax = [PU, T(R.f(8, 16)), ...frond(R.i(12, 14), R.f(.64, .74), R.f(1.2, 1.45)), PO,\n      PU, T(-R.f(14, 24)), ...frond(R.i(10, 12), R.f(.56, .64), R.f(.95, 1.2)), PO,\n      PU, T(R.f(-4, 2)), ...young, PO];\n    mods = derive(ax, rules, 2, {});\n    P.roots = 'rhizome';\n    P.fcol = FLOWER_PALETTES[0];\n  } else if (habit === 'scandens'){\n    const N = R.i(11, 14), l = R.f(.7, .85);\n    P.leafShape = R.pick(['cordate', 'cordate', 'ovate', 'lobed']);\n    P.stem = '#666238'; P.wUnit = 3.8; P.taper = .975; P.branchW = .7; P.curl = .2; P.jit = 6;\n    P.trop = { t: -90, e: R.f(3.5, 5.5) };\n    P.pet = R.f(.18, .32);\n    const vine = (n, len, first) => {\n      const out = [];\n      for (let k = 0; k < n; k++){\n        const sg = k % 2 ? 1 : -1;\n        out.push(F(len * R.f(.85, 1.15)), T(R.f(-12, 12)));\n        out.push(PU, T(sg * R.f(45, 70)), Lf(R.f(.95, 1.3) * (1 - k / n * .35)), PO);\n        if (k % 3 === 2) out.push(PU, T(-sg * R.f(20, 40)), F(.35, .35), Ry(1), PO);\n        else if (k % 4 === 1 && k > 1){\n          const tsg = R.sg();\n          out.push(PU, T(-sg * 30), F(.18, .25));\n          for (let i = 0; i < 16; i++) out.push(T(tsg * (22 + i * 3)), F(.1 * (1 - i / 20), .22));\n          out.push(PO);\n        } else if (first && k === 5) out.push(PU, T(-sg * 35), F(.25, .35), K(.5), PO);\n      }\n      out.push(F(len * .6), Bd(.5));\n      return out;\n    };\n    P.flowerType = 'star';\n    mods = [PU, T(R.f(-14, -4)), ...vine(N, l, true), PO, PU, T(R.f(10, 24)), ...vine(Math.round(N * .55), l * .85, false), PO];\n    P.roots = 'fibrous';\n  } else {\n    // rosula\n    const nL = R.i(6, 9), leafSz = R.f(2.1, 2.8), scapes = R.i(1, 3);\n    P.leafShape = R.pick(['pinnatifid', 'spathulate', 'lanceolate', 'pinnatifid']);\n    P.serr = P.leafShape === 'lanceolate' || P.leafShape === 'spathulate' ? R.f(.08, .18) : 0;\n    P.pet = R.f(.02, .1); P.wUnit = 3.2; P.taper = .985; P.curl = .06;\n    P.trop = { t: 90, e: 2 };\n    const out = [];\n    for (let i = 0; i < nL; i++){\n      const a = -84 + 168 * i / (nL - 1) + R.f(-6, 6);\n      out.push(PU, T(a), Lf(leafSz * R.f(.75, 1.05) * (.78 + .38 * Math.abs(a) / 84)), PO);\n    }\n    const headType = R.pick(['ray', 'ray', 'clock', 'star']);\n    for (let s = 0; s < scapes; s++){\n      const m = R.i(7, 10), a = scapes === 1 ? R.f(-6, 6) : -16 + 32 * s / (scapes - 1) + R.f(-4, 4);\n      out.push(PU, T(a));\n      for (let j = 0; j < m; j++){\n        out.push(F(R.f(.62, .78) * (s === 1 ? .8 : 1)));\n        if (j === 3 && R.ch(.5)) out.push(PU, T(40), Lf(.5, { shape: 'linear' }), PO);\n      }\n      const ht = s === 0 ? headType : R.pick(['clock', 'bud', headType]);\n      if (ht === 'clock') out.push(Hd(1));\n      else if (ht === 'bud') out.push(T(R.sg() * 50), F(.3, .8), Bd(.8));\n      else out.push(K(R.f(.8, 1), { type: ht }));\n      out.push(PO);\n    }\n    mods = out;\n    P.flowerType = 'ray';\n    P.petals = R.i(13, 19);\n    P.roots = 'taproot';\n  }\n  const geom = interpret(mods, P, R);\n  return { P, geom, R };\n}\n\n/* ------------------------------------------------------------------\n   Drawing helpers\n------------------------------------------------------------------ */\nconst SHAPES = {\n  lanceolate: { w: .19, f: (t) => Math.pow(Math.sin(Math.PI * Math.pow(t, .78)), .9) },\n  ovate: { w: .33, f: (t) => Math.sin(Math.PI * Math.pow(t, .62)) },\n  cordate: { w: .42, f: (t) => Math.sin(Math.PI * Math.pow(t, .7)), cord: true },\n  linear: { w: .06, f: (t) => Math.pow(1 - Math.pow(t, 2.4), .7) * Math.min(1, t * 10) },\n  lobed: { w: .34, f: (t) => Math.sin(Math.PI * Math.pow(t, .75)) * (.6 + .4 * Math.abs(Math.sin(Math.PI * t * 4.5))) },\n  pinnatifid: { w: .36, f: (t) => Math.sin(Math.PI * Math.pow(t, .8)) * (.26 + .74 * Math.pow(Math.abs(Math.sin(Math.PI * t * 5.5)), .7)) },\n  orbicular: { w: .46, f: (t) => Math.pow(Math.sin(Math.PI * t), .55) },\n  spathulate: { w: .26, f: (t) => Math.pow(t, 1.4) * Math.pow(1 - t, .35) * 2.4 },\n  oblong: { w: .24, f: (t) => Math.pow(Math.sin(Math.PI * t), .45) }\n};\nconst f2 = (p) => n1(p[0]) + ' ' + n1(p[1]);\nfunction smoothPath(pts, closed){\n  let d = 'M' + f2(pts[0]);\n  for (let i = 1; i < pts.length - 1; i++){\n    const m = [(pts[i][0] + pts[i + 1][0]) / 2, (pts[i][1] + pts[i + 1][1]) / 2];\n    d += 'Q' + f2(pts[i]) + ' ' + f2(m);\n  }\n  d += 'L' + f2(pts[pts.length - 1]);\n  return closed ? d + 'Z' : d;\n}\nfunction polyPath(pts){\n  let d = 'M' + f2(pts[0]);\n  for (let i = 1; i < pts.length; i++) d += 'L' + f2(pts[i]);\n  return d + 'Z';\n}\n\n/* one leaf, drawn around its attachment point (0,0) */\nfunction leafMarkup(L, ang, shapeName, o){\n  const S = SHAPES[shapeName] || SHAPES.lanceolate;\n  const W = L * S.w * o.wMul, serr = o.serr, N = serr ? 44 : 20;\n  const pet = o.pet * L, ca = Math.cos(ang), sa = Math.sin(ang);\n  const tr = (u, v) => [u * ca - v * sa, u * sa + v * ca];\n  const top = [], bot = [], mid = [];\n  for (let i = 0; i <= N; i++){\n    const t = i / N;\n    let hw = W * S.f(t);\n    if (serr && t > .08 && t < .95){ const q = (t * o.teeth) % 1; hw *= 1 + serr * (q - .5) * 2; }\n    const u = pet + L * (S.cord ? t - 2.2 * t * Math.pow(1 - t, 5) : t);\n    const bend = o.curl * L * t * t;\n    top.push(tr(u, bend + hw)); bot.push(tr(u, bend - hw * o.asym));\n    mid.push(tr(pet + L * t, bend));\n  }\n  const outline = top.concat(bot.slice().reverse());\n  const body = serr ? polyPath(outline) : smoothPath(outline, true);\n  let s = '';\n  if (pet > .5) s += `<path d=\"M0 0L${f2(tr(pet + L * .02, 0))}\" fill=\"none\" stroke=\"${o.stem}\" stroke-width=\"${n1(clamp(L * .03, .7, 2.2))}\" stroke-linecap=\"round\"/>`;\n  s += `<path d=\"${body}\" fill=\"${o.fill}\" stroke=\"rgba(62,44,26,.82)\" stroke-width=\"${L < 14 ? .5 : .8}\" stroke-linejoin=\"round\"/>`;\n  if (L >= 14){\n    // shade one half of the blade, like a watercolour wash\n    const half = top.concat(mid.slice().reverse());\n    s += `<path d=\"${smoothPath(half, true)}\" fill=\"${o.shade}\" opacity=\".3\"/>`;\n    let v = `M${f2(mid[0])}` + mid.slice(1, -1).map((p, i) => (i % 2 ? '' : 'L' + f2(p))).join('') + 'L' + f2(mid[N - 1]);\n    if (L > 24){\n      const nv = clamp(Math.round(L / 13), 3, 8);\n      for (let k = 1; k <= nv; k++){\n        const t = k / (nv + 1.4), i0 = Math.round(t * N), i1 = Math.min(N, Math.round((t + .16) * N));\n        const a = mid[i0], b1 = top[i1], b2 = bot[i1];\n        const e1 = [a[0] + (b1[0] - a[0]) * .82, a[1] + (b1[1] - a[1]) * .82];\n        const e2 = [a[0] + (b2[0] - a[0]) * .82, a[1] + (b2[1] - a[1]) * .82];\n        v += `M${f2(a)}L${f2(e1)}M${f2(a)}L${f2(e2)}`;\n      }\n    }\n    s += `<path d=\"${v}\" fill=\"none\" stroke=\"rgba(62,44,26,.42)\" stroke-width=\"${L > 40 ? .75 : .5}\" stroke-linecap=\"round\"/>`;\n  }\n  if (o.sori && L > 7){\n    for (let k = 0; k < 3; k++){\n      const t = .32 + k * .2, i = Math.round(t * N);\n      const p1 = [(mid[i][0] * 2 + top[i][0]) / 3, (mid[i][1] * 2 + top[i][1]) / 3];\n      const p2 = [(mid[i][0] * 2 + bot[i][0]) / 3, (mid[i][1] * 2 + bot[i][1]) / 3];\n      const r = n1(clamp(L * .07, .7, 1.6));\n      s += `<circle cx=\"${n1(p1[0])}\" cy=\"${n1(p1[1])}\" r=\"${r}\" fill=\"#8a4a28\"/><circle cx=\"${n1(p2[0])}\" cy=\"${n1(p2[1])}\" r=\"${r}\" fill=\"#8a4a28\"/>`;\n    }\n  }\n  return s;\n}\n\nfunction petalPath(len, wid, ang, notch){\n  const ca = Math.cos(ang), sa = Math.sin(ang), pts = [], N = 10;\n  const tr = (u, v) => [u * ca - v * sa, u * sa + v * ca];\n  const prof = (t) => Math.pow(Math.sin(Math.PI * Math.pow(t, .55)), .8);\n  for (let i = 0; i <= N; i++){ const t = i / N; pts.push(tr(len * (notch && i === N ? .9 : t), wid * prof(t))); }\n  for (let i = N; i >= 0; i--){ const t = i / N; pts.push(tr(len * (notch && i === N ? .9 : t), -wid * prof(t))); }\n  return smoothPath(pts, true);\n}\n\nfunction flowerMarkup(fl, P, R, s){\n  const c = P.fcol;\n  let out = '';\n  if (fl.type === 'floret'){\n    const r = clamp(fl.sz * s * .3, 1.7, 3.4);\n    out += `<circle r=\"${n1(r)}\" fill=\"${c.petal}\" stroke=\"rgba(62,44,26,.7)\" stroke-width=\".45\"/><circle r=\"${n1(r * .32)}\" fill=\"${c.edge}\"/>`;\n    return out;\n  }\n  if (fl.type === 'bell'){\n    const Lb = clamp(fl.sz * s * .42, 11, 28), w0 = Lb * .16;\n    const dir = -fl.h * DEG;\n    let vx = Math.cos(dir) * .45, vy = Math.sin(dir) * .45 + .55;\n    const a = Math.atan2(vy, vx), ca = Math.cos(a), sa = Math.sin(a);\n    const tr = (u, v) => [u * ca - v * sa, u * sa + v * ca];\n    const p = [[0, -w0], [Lb * .45, -w0 * 1.5], [Lb * .82, -w0 * 1.85], [Lb * 1.02, -w0 * 2.7], [Lb * .96, -w0 * 1.1], [Lb * 1.04, -w0 * .2], [Lb * .96, w0 * .6], [Lb * 1.03, w0 * 1.6], [Lb * 1.0, w0 * 2.7], [Lb * .82, w0 * 1.85], [Lb * .45, w0 * 1.5], [0, w0]];\n    out += `<path d=\"${smoothPath(p.map((q) => tr(q[0], q[1])), true)}\" fill=\"${c.petal}\" stroke=\"${c.edge}\" stroke-width=\".8\" stroke-linejoin=\"round\"/>`;\n    out += `<path d=\"M${f2(tr(Lb * .1, -w0 * .4))}Q${f2(tr(Lb * .55, -w0 * 1.1))} ${f2(tr(Lb * .92, -w0 * 1.9))}M${f2(tr(Lb * .1, w0 * .4))}Q${f2(tr(Lb * .55, w0 * 1.1))} ${f2(tr(Lb * .92, w0 * 1.9))}\" fill=\"none\" stroke=\"${c.edge}\" stroke-width=\".5\" opacity=\".7\"/>`;\n    out += `<path d=\"M${f2(tr(Lb * .95, 0))}L${f2(tr(Lb * 1.2, w0 * .3))}\" stroke=\"rgba(62,44,26,.8)\" stroke-width=\".6\"/><circle cx=\"${n1(tr(Lb * 1.22, w0 * .3)[0])}\" cy=\"${n1(tr(Lb * 1.22, w0 * .3)[1])}\" r=\"1.2\" fill=\"${c.centre}\" stroke=\"rgba(62,44,26,.7)\" stroke-width=\".4\"/>`;\n    out += `<path d=\"M${f2(tr(-1, -w0 * 1.2))}L${f2(tr(Lb * .22, 0))}L${f2(tr(-1, w0 * 1.2))}Z\" fill=\"#6b7f4e\" stroke=\"rgba(62,44,26,.7)\" stroke-width=\".5\"/>`;\n    return out;\n  }\n  if (fl.type === 'ray'){\n    const r = clamp(fl.sz * s * .5, 16, 40), n = P.petals, rot = R.f(0, 360);\n    for (let i = 0; i < n; i++){\n      const a = (rot + i * 360 / n + R.f(-4, 4)) * DEG, len = r * R.f(.9, 1.05);\n      out += `<path d=\"${petalPath(len, r * .12, a, true)}\" fill=\"${c.petal}\" stroke=\"${c.edge}\" stroke-width=\".55\"/>`;\n    }\n    const dr = r * .3;\n    out += `<circle r=\"${n1(dr)}\" fill=\"${c.centre}\" stroke=\"rgba(62,44,26,.8)\" stroke-width=\".7\"/>`;\n    for (let i = 1; i < 34; i++){\n      const rr = dr * .9 * Math.sqrt(i / 34), a = i * 137.508 * DEG;\n      out += `<circle cx=\"${n1(Math.cos(a) * rr)}\" cy=\"${n1(Math.sin(a) * rr)}\" r=\"${n1(dr * .075 + .25)}\" fill=\"rgba(74,44,20,.75)\"/>`;\n    }\n    return out;\n  }\n  // star: face-on flower\n  const r = clamp(fl.sz * s * .42, 6, 24), n = P.petals, rot = R.f(0, 360);\n  for (let i = 0; i < n; i++){\n    const a = (rot + i * 360 / n) * DEG;\n    out += `<path d=\"${petalPath(r, r * (n > 5 ? .32 : .42), a, false)}\" fill=\"${c.petal}\" stroke=\"${c.edge}\" stroke-width=\".6\"/>`;\n    out += `<path d=\"M0 0L${n1(Math.cos(a) * r * .7)} ${n1(Math.sin(a) * r * .7)}\" stroke=\"${c.edge}\" stroke-width=\".4\" opacity=\".6\"/>`;\n  }\n  out += `<circle r=\"${n1(r * .24)}\" fill=\"${c.centre}\" stroke=\"rgba(62,44,26,.8)\" stroke-width=\".6\"/>`;\n  for (let i = 0; i < 7; i++){\n    const a = (i / 7) * Math.PI * 2 + rot;\n    out += `<circle cx=\"${n1(Math.cos(a) * r * .34)}\" cy=\"${n1(Math.sin(a) * r * .34)}\" r=\".9\" fill=\"rgba(62,44,26,.85)\"/>`;\n  }\n  return out;\n}\n\n/* ------------------------------------------------------------------\n   The specimen: grow, fit to the sheet, mount, label\n------------------------------------------------------------------ */\nlet nextNo = 1400 + Math.floor(Math.random() * 90);\nlet nextSeed = (Date.now() ^ (Math.random() * 1e9)) >>> 0;\n\nfunction makeSpecimen(habit, speedMode){\n  const seed = (nextSeed = (nextSeed * 1103515245 + 12345) >>> 0);\n  const { P, geom, R } = buildSpecies(seed, habit);\n  const no = nextNo++;\n  const nm = makeName(R);\n  const sp = {\n    seed, habit, no, genus: nm.genus, epithet: nm.epithet,\n    family: R.pick(FAMILIES), author: R.pick(AUTHORS), collector: R.pick(COLLECTORS), locality: R.pick(LOCALITIES),\n    day: R.i(1, 28), month: R.i(3, 9), year: R.i(1851, 1899),\n    vern: R.pick(VERN_A) + (R.ch(.5) ? ' ' : ' ') + R.pick(VERN_B[habit]),\n    whimsy: R.pick(WHIMSY), P, rot: R.f(-.9, .9)\n  };\n  sp.fox = foxing(R);\n  const art = drawSheet(sp, geom, R, speedMode);\n  sp.plantSVG = art.plant; sp.furnSVG = art.furn; sp.total = art.total; sp.heightCm = art.heightCm;\n  return sp;\n}\n\nfunction foxing(R){\n  const spots = [];\n  const n = R.i(4, 9);\n  for (let i = 0; i < n; i++){\n    const x = R.f(3, 97).toFixed(1), y = R.f(3, 97).toFixed(1), r = R.f(1, 3.4), a = R.f(.08, .2);\n    spots.push(`radial-gradient(circle at ${x}% ${y}%,rgba(150,98,46,${a.toFixed(2)}) 0 ${r.toFixed(1)}px,rgba(150,98,46,${(a * .35).toFixed(2)}) ${(r * 2.4).toFixed(1)}px,transparent ${(r * 5.5).toFixed(1)}px)`);\n  }\n  spots.push(`linear-gradient(${R.i(0, 360)}deg,rgba(170,128,70,.07),transparent 40%)`);\n  return spots.join(',');\n}\n\nfunction drawSheet(sp, g, R, speedMode){\n  const P = sp.P;\n  const box = { x0: 52, y0: 60, x1: 548, y1: 648 };\n  // bounding box of the plant in turtle space\n  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;\n  const add = (x, y) => { if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y; };\n  for (const q of g.segs){ add(q.x1, q.y1); add(q.x2, q.y2); }\n  for (const l of g.leaves){\n    const a = l.h * DEG, L = l.sz * (1 + P.pet), w = l.sz * ((SHAPES[l.shape] || SHAPES.lanceolate).w);\n    add(l.x + Math.cos(a) * L, l.y + Math.sin(a) * L);\n    add(l.x + Math.cos(a) * L * .5 - Math.sin(a) * w, l.y + Math.sin(a) * L * .5 + Math.cos(a) * w);\n    add(l.x + Math.cos(a) * L * .5 + Math.sin(a) * w, l.y + Math.sin(a) * L * .5 - Math.cos(a) * w);\n  }\n  for (const f of g.flowers){ const r = f.type === 'floret' ? .06 : f.type === 'bell' ? f.sz * .55 : f.sz * .45; add(f.x - r, f.y - r); add(f.x + r, f.y + r); }\n  for (const b of g.berries){ add(b.x - .25, b.y - .45); add(b.x + .25, b.y + .05); }\n  for (const h of g.heads){ add(h.x - .6, h.y - .6); add(h.x + .6, h.y + .6); }\n  for (const b of g.buds){ add(b.x, b.y); }\n  const bw = Math.max(.5, maxX - minX), bh = Math.max(.5, maxY - minY);\n  const s = Math.min((box.x1 - box.x0) / bw, (box.y1 - box.y0) / bh, 150);\n  const ox = (box.x0 + box.x1) / 2 - s * (minX + maxX) / 2;\n  const oy = box.y1 + s * minY - Math.max(0, ((box.y1 - box.y0) - s * bh) * .15);\n  const X = (x) => ox + s * x, Y = (y) => oy - s * y;\n\n  // timing: every stroke is inked at one steady speed\n  let maxDist = 1;\n  for (const q of g.segs) maxDist = Math.max(maxDist, (q.d0 + q.len) * s);\n  const growDur = speedMode === 'fast' ? .95 : 3.6;\n  const speed = maxDist / growDur;\n  const unfurl = speedMode === 'fast' ? .38 : .75;\n  let total = 0;\n  const tm = (d) => d * s / speed;\n\n  let plant = '';\n  // roots first, growing down from the crown\n  const rootData = drawRoots(X(0), Y(0), P, R, speed);\n  plant += rootData.svg;\n  total = Math.max(total, rootData.end);\n\n  // stems\n  let stems = `<g fill=\"none\" stroke=\"${P.stem}\" stroke-linecap=\"round\" stroke-linejoin=\"round\">`;\n  let hl = `<g fill=\"none\" stroke=\"rgba(214,210,160,.55)\" stroke-linecap=\"round\">`;\n  for (const q of g.segs){\n    const t0 = tm(q.d0), dur = Math.max(.015, tm(q.len));\n    const sw = Math.max(.55, q.w * P.wUnit);\n    const d = `M${n1(X(q.x1))} ${n1(Y(q.y1))}Q${n1(X(q.cx))} ${n1(Y(q.cy))} ${n1(X(q.x2))} ${n1(Y(q.y2))}`;\n    stems += `<path class=\"st\" pathLength=\"1\" d=\"${d}\" stroke-width=\"${sw.toFixed(2)}\" style=\"--d:${t0.toFixed(3)}s;--t:${dur.toFixed(3)}s\"/>`;\n    if (sw > 2.6){\n      const a = -q.h * DEG + Math.PI / 2, off = sw * .2, dx = Math.cos(a) * off, dy = Math.sin(a) * off;\n      hl += `<path class=\"st\" pathLength=\"1\" d=\"M${n1(X(q.x1) + dx)} ${n1(Y(q.y1) + dy)}Q${n1(X(q.cx) + dx)} ${n1(Y(q.cy) + dy)} ${n1(X(q.x2) + dx)} ${n1(Y(q.y2) + dy)}\" stroke-width=\"${(sw * .28).toFixed(2)}\" style=\"--d:${t0.toFixed(3)}s;--t:${dur.toFixed(3)}s\"/>`;\n    }\n    total = Math.max(total, t0 + dur);\n  }\n  plant += stems + '</g>' + hl + '</g>';\n\n  // leaves\n  const shadeCol = '#3f4a2a';\n  for (const l of g.leaves){\n    const L = l.sz * s, ang = -l.h * DEG;\n    const roll = R.r();\n    let fill = mix('#6b7f4e', '#9aa77a', clamp(P.greenBias * .6 + R.r() * .55, 0, 1));\n    if (P.habit !== 'filix'){\n      if (roll < .1) fill = mix(fill, '#b9a96a', R.f(.45, .8));\n      else if (roll < .15) fill = mix(fill, '#9c7a4a', R.f(.4, .7));\n    }\n    if (l.shape === 'linear') fill = mix(fill, '#8a9a62', .5);\n    const o = { wMul: P.wMul * R.f(.9, 1.08), serr: P.serr, teeth: P.teeth, curl: P.curlLeaf * R.sg() * R.f(.4, 1.2), asym: R.f(.86, 1.05),\n      pet: l.shape === 'oblong' || l.shape === 'linear' ? 0 : P.pet, fill, shade: shadeCol, stem: P.stem, sori: l.sori };\n    const t0 = tm(l.d) + .04;\n    plant += `<g transform=\"translate(${n1(X(l.x))} ${n1(Y(l.y))})\"><g class=\"gl\" style=\"--d:${t0.toFixed(3)}s;--u:${unfurl}s\">${leafMarkup(L, ang, l.shape, o)}</g></g>`;\n    total = Math.max(total, t0 + unfurl);\n  }\n  // buds\n  for (const b of g.buds){\n    const L = clamp(b.sz * s * .22, 5, 14), a = -b.h * DEG, ca = Math.cos(a), sa = Math.sin(a);\n    const tr = (u, v) => [u * ca - v * sa, u * sa + v * ca];\n    const pts = [[0, 0], [L * .35, L * .3], [L * .8, L * .18], [L, 0], [L * .8, -L * .18], [L * .35, -L * .3], [0, 0]].map((q) => tr(q[0], q[1]));\n    const t0 = tm(b.d) + .1;\n    plant += `<g transform=\"translate(${n1(X(b.x))} ${n1(Y(b.y))})\"><g class=\"gl\" style=\"--d:${t0.toFixed(3)}s;--u:${unfurl}s\"><path d=\"${smoothPath(pts, true)}\" fill=\"#7d8c56\" stroke=\"rgba(62,44,26,.8)\" stroke-width=\".6\"/><path d=\"M${f2(tr(L * .62, 0))}L${f2(tr(L, 0))}\" stroke=\"${P.fcol.petal}\" stroke-width=\"${n1(L * .22)}\" stroke-linecap=\"round\"/></g></g>`;\n    total = Math.max(total, t0 + unfurl);\n  }\n  // flowers\n  for (const f of g.flowers){\n    const t0 = tm(f.d) + unfurl * .6;\n    const dur = speedMode === 'fast' ? .45 : .95;\n    plant += `<g transform=\"translate(${n1(X(f.x))} ${n1(Y(f.y))})\"><g class=\"gf\" style=\"--d:${t0.toFixed(3)}s;--u:${dur}s\">${flowerMarkup(f, P, R, s)}</g></g>`;\n    total = Math.max(total, t0 + dur);\n  }\n  // berries hang in clusters\n  for (const b of g.berries){\n    const n = R.i(3, 7), rb = clamp(s * .1, 3.2, 7.2), bx = X(b.x), by = Y(b.y);\n    const items = [];\n    for (let i = 0; i < n; i++){\n      const a = (90 + R.f(-70, 70)) * DEG, dd = rb * R.f(1.2, 3.2);\n      items.push({ x: Math.cos(a) * dd, y: Math.sin(a) * dd + rb * .6, r: rb * R.f(.8, 1.1), c: mix(P.berry, '#5e1714', R.f(0, .45)) });\n    }\n    items.sort((p, q) => p.y - q.y);\n    let inner = '';\n    for (const it of items) inner += `<path d=\"M0 0Q${n1(it.x * .2)} ${n1(it.y * .6)} ${n1(it.x)} ${n1(it.y - it.r)}\" fill=\"none\" stroke=\"${P.stem}\" stroke-width=\".6\"/>`;\n    for (const it of items){\n      inner += `<circle cx=\"${n1(it.x)}\" cy=\"${n1(it.y)}\" r=\"${n1(it.r)}\" fill=\"${it.c}\" stroke=\"rgba(52,30,18,.85)\" stroke-width=\".6\"/>`;\n      inner += `<circle cx=\"${n1(it.x - it.r * .35)}\" cy=\"${n1(it.y - it.r * .38)}\" r=\"${n1(it.r * .28)}\" fill=\"rgba(255,238,222,.62)\"/>`;\n      inner += `<path d=\"M${n1(it.x - it.r * .25)} ${n1(it.y + it.r * .7)}l${n1(it.r * .5)} 0M${n1(it.x)} ${n1(it.y + it.r * .45)}l0 ${n1(it.r * .5)}\" stroke=\"rgba(52,30,18,.7)\" stroke-width=\".45\"/>`;\n    }\n    const t0 = tm(b.d) + unfurl * .7;\n    plant += `<g transform=\"translate(${n1(bx)} ${n1(by)})\"><g class=\"gf\" style=\"--d:${t0.toFixed(3)}s;--u:.8s\">${inner}</g></g>`;\n    total = Math.max(total, t0 + .8);\n  }\n  // seed clocks\n  for (const h of g.heads){\n    const Lr = clamp(h.sz * s * .52, 18, 46), n = 40;\n    let inner = `<circle r=\"${n1(Lr * .1)}\" fill=\"#8a6a3c\" stroke=\"rgba(62,44,26,.8)\" stroke-width=\".5\"/>`;\n    for (let i = 0; i < n; i++){\n      const a = i / n * Math.PI * 2 + R.f(-.05, .05), L = Lr * R.f(.86, 1.02), ca = Math.cos(a), sa = Math.sin(a);\n      const ex = ca * L, ey = sa * L;\n      inner += `<path d=\"M${n1(ca * Lr * .12)} ${n1(sa * Lr * .12)}L${n1(ca * Lr * .26)} ${n1(sa * Lr * .26)}\" stroke=\"#5c4424\" stroke-width=\"1.3\" stroke-linecap=\"round\"/>`;\n      inner += `<path d=\"M${n1(ca * Lr * .26)} ${n1(sa * Lr * .26)}L${n1(ex)} ${n1(ey)}\" stroke=\"rgba(74,54,34,.55)\" stroke-width=\".35\"/>`;\n      let tuft = '';\n      for (let j = -2; j <= 2; j++){ const b2 = a + j * .28; tuft += `M${n1(ex)} ${n1(ey)}l${n1(Math.cos(b2) * Lr * .16)} ${n1(Math.sin(b2) * Lr * .16)}`; }\n      inner += `<path d=\"${tuft}\" stroke=\"rgba(74,54,34,.42)\" stroke-width=\".3\" fill=\"none\"/>`;\n    }\n    const t0 = tm(h.d) + unfurl * .6;\n    plant += `<g transform=\"translate(${n1(X(h.x))} ${n1(Y(h.y))})\"><g class=\"gf\" style=\"--d:${t0.toFixed(3)}s;--u:1s\">${inner}</g></g>`;\n    total = Math.max(total, t0 + 1);\n  }\n\n  /* furniture: tape, label, stamp, scale, packet */\n  let furn = '';\n  const fast = speedMode === 'fast';\n  const tapeT = fast ? total * .62 : total + .25;\n  const labT = fast ? .12 : tapeT + .35;\n  const main = g.segs.filter((q) => q.w * P.wUnit > 1.3 && q.dep <= 1 && q.len * s > 10);\n  const picks = [];\n  if (main.length){\n    const maxD = Math.max(...main.map((q) => q.d0));\n    for (const frac of [.14, .46]){\n      let best = null, bd = 1e9;\n      for (const q of main){ const dd = Math.abs(q.d0 - maxD * frac); if (dd < bd){ bd = dd; best = q; } }\n      if (best && !picks.includes(best)) picks.push(best);\n    }\n  }\n  if (P.habit === 'rosula' || P.habit === 'umbella'){\n    const big = g.leaves.slice().sort((a, b) => b.sz - a.sz)[0];\n    if (big) picks.push({ leaf: big });\n  }\n  picks.slice(0, 3).forEach((q, i) => {\n    let x, y, a;\n    if (q.leaf){\n      const la = q.leaf.h * DEG, L = q.leaf.sz * .55;\n      x = X(q.leaf.x + Math.cos(la) * L); y = Y(q.leaf.y + Math.sin(la) * L); a = -q.leaf.h + 90;\n    } else {\n      x = X((q.x1 + q.x2) / 2); y = Y((q.y1 + q.y2) / 2); a = -q.h + 90;\n    }\n    a += R.f(-14, 14);\n    furn += tapeMarkup(x, y, a, R.f(58, 76), R.f(15, 19), tapeT + i * .12, R);\n  });\n\n  const upc = R.f(10, 23); // sheet units per centimetre\n  const heightCm = Math.round((bh * s) / upc);\n  furn += labelMarkup(sp, labT);\n  furn += stampMarkup(sp, fast ? .3 : labT + .45, R);\n  furn += scaleMarkup(upc, fast ? .2 : labT + .15);\n  const pMaxX = X(maxX), pMinY = Y(maxY);\n  if ((pMaxX < 432 || pMinY > 190) && R.ch(.75)) furn += packetMarkup(P, fast ? .25 : labT + .25, R);\n  if (R.ch(.5)) furn += slipMarkup(sp, fast ? .35 : labT + .1, R);\n  total = Math.max(total, tapeT + .6, labT + 1);\n  return { plant, furn, total, heightCm };\n}\n\nfunction drawRoots(bx, by, P, R, speed){\n  let svg = `<g fill=\"none\" stroke=\"#6e5436\" stroke-linecap=\"round\" stroke-linejoin=\"round\">`;\n  let end = 0;\n  const seg = (x1, y1, x2, y2, w, d0, len) => {\n    const t0 = d0 / speed, dur = Math.max(.01, len / speed);\n    svg += `<path class=\"st\" pathLength=\"1\" d=\"M${n1(x1)} ${n1(y1)}L${n1(x2)} ${n1(y2)}\" stroke-width=\"${n1(Math.max(.35, w))}\" style=\"--d:${t0.toFixed(3)}s;--t:${dur.toFixed(3)}s\"/>`;\n    end = Math.max(end, t0 + dur);\n  };\n  const ok = (x, y) => y < 752 && !(x > 314 && y > 676) && x > 28 && x < 572;\n  const branch = (x, y, a, len, w, dep, dist) => {\n    const steps = R.i(4, 7);\n    let px = x, py = y;\n    for (let i = 0; i < steps; i++){\n      a += R.f(-.35, .35); a += (Math.PI / 2 - a) * .12;\n      const l = len / steps, nx = px + Math.cos(a) * l, ny = py + Math.sin(a) * l;\n      if (!ok(nx, ny)) break;\n      const ww = w * (1 - i / steps * .6);\n      seg(px, py, nx, ny, ww, dist, l);\n      if (dep < 2 && R.ch(.33)) branch(nx, ny, a + R.sg() * R.f(.4, 1.1), len * .5, ww * .6, dep + 1, dist + l);\n      px = nx; py = ny; dist += l;\n    }\n  };\n  if (P.roots === 'taproot'){\n    let x = bx, y = by, a = Math.PI / 2 + R.f(-.15, .15), w = 7.5, dist = 0;\n    const steps = 9, len = R.f(72, 96);\n    for (let i = 0; i < steps; i++){\n      a += R.f(-.18, .18); a += (Math.PI / 2 - a) * .2;\n      const l = len / steps, nx = x + Math.cos(a) * l, ny = y + Math.sin(a) * l;\n      if (!ok(nx, ny)) break;\n      seg(x, y, nx, ny, w, dist, l);\n      if (i > 1 && R.ch(.55)) branch(nx, ny, a + R.sg() * R.f(.7, 1.2), R.f(18, 34), .8, 1, dist + l);\n      x = nx; y = ny; dist += l; w *= .8;\n    }\n  } else if (P.roots === 'rhizome'){\n    const x0 = bx - R.f(50, 70), x1 = bx + R.f(40, 60);\n    let dist = 0, px = x0, py = by + 4;\n    for (let i = 1; i <= 8; i++){\n      const nx = x0 + (x1 - x0) * i / 8, ny = by + 4 + Math.sin(i * 1.3) * 2.5;\n      seg(px, py, nx, ny, 6.2, dist, nx - px);\n      px = nx; py = ny; dist += (x1 - x0) / 8;\n    }\n    for (let i = 0; i < 16; i++){\n      const x = x0 + (x1 - x0) * (i + .5) / 16;\n      svg += `<path d=\"M${n1(x)} ${n1(by + 1)}l${n1(R.f(-3, 3))} ${n1(R.f(-6, -3))}\" stroke=\"#7a5a32\" stroke-width=\".7\"/>`;\n    }\n    for (let i = 0; i < 7; i++) branch(x0 + (x1 - x0) * R.f(.05, .95), by + 6, Math.PI / 2 + R.f(-.8, .8), R.f(26, 48), 1, 1, 10);\n  } else if (P.roots === 'woody'){\n    for (let i = 0; i < 4; i++) branch(bx + R.f(-3, 3), by, Math.PI / 2 + R.f(-1, 1), R.f(40, 70), 3.2, 0, 0);\n  } else {\n    const n = R.i(6, 9);\n    for (let i = 0; i < n; i++) branch(bx + R.f(-5, 5), by, Math.PI / 2 + R.f(-1.1, 1.1), R.f(30, 58), 1.3, 1, 0);\n  }\n  svg += '</g>';\n  // crumbs of soil clinging to the roots\n  for (let i = 0; i < 9; i++){\n    const x = bx + R.f(-40, 40), y = by + R.f(6, 40);\n    if (!ok(x, y)) continue;\n    svg += `<ellipse cx=\"${n1(x)}\" cy=\"${n1(y)}\" rx=\"${n1(R.f(.8, 2.2))}\" ry=\"${n1(R.f(.6, 1.6))}\" fill=\"rgba(110,82,48,.45)\"/>`;\n  }\n  return { svg, end };\n}\n\nfunction tapeMarkup(x, y, a, L, W, t, R){\n  const pts = [];\n  const teeth = 4, h = W / 2, l = L / 2;\n  pts.push([-l, -h]);\n  pts.push([l, -h]);\n  for (let i = 1; i <= teeth * 2; i++) pts.push([l + (i % 2 ? R.f(1.6, 3.2) : 0), -h + W * i / (teeth * 2)]);\n  pts.push([-l, h]);\n  for (let i = teeth * 2 - 1; i >= 1; i--) pts.push([-l - (i % 2 ? R.f(1.6, 3.2) : 0), -h + W * i / (teeth * 2)]);\n  const d = polyPath(pts);\n  return `<g transform=\"translate(${n1(x)} ${n1(y)}) rotate(${n1(a)})\"><g class=\"tape\" style=\"--d:${t.toFixed(2)}s\">` +\n    `<path d=\"${d}\" transform=\"translate(1.2 1.8)\" fill=\"rgba(60,40,20,.13)\"/>` +\n    `<path d=\"${d}\" fill=\"rgba(234,222,190,.8)\" stroke=\"rgba(150,122,80,.35)\" stroke-width=\".6\"/>` +\n    `<path d=\"M${n1(-l + 4)} ${n1(-h + 3.5)}H${n1(l - 6)}M${n1(-l + 8)} ${n1(h - 4)}H${n1(l - 3)}\" stroke=\"rgba(255,255,255,.4)\" stroke-width=\".8\"/>` +\n    `</g></g>`;\n}\n\nfunction labelMarkup(sp, t){\n  const name = sp.genus + ' ' + sp.epithet;\n  const fs = Math.min(23, 226 / (name.length * .47));\n  const date = `${sp.day}.${ROMAN[sp.month - 1]}.${sp.year}`;\n  const loc = sp.locality.length > 30 ? sp.locality.slice(0, 29) + '…' : sp.locality;\n  return `<g transform=\"translate(318 686)\"><g class=\"ink-late\" style=\"--d:${t.toFixed(2)}s\">` +\n    `<rect x=\"2.5\" y=\"3\" width=\"252\" height=\"132\" fill=\"rgba(74,54,34,.12)\"/>` +\n    `<rect width=\"252\" height=\"132\" fill=\"#f9f3e3\" stroke=\"#4a3622\" stroke-width=\"1\"/>` +\n    `<rect x=\"5\" y=\"5\" width=\"242\" height=\"122\" fill=\"none\" stroke=\"#4a3622\" stroke-width=\".45\"/>` +\n    `<text x=\"126\" y=\"22\" text-anchor=\"middle\" class=\"t-caps\">HERBARIUM IMAGINARIUM</text>` +\n    `<path d=\"M20 29H232\" stroke=\"#4a3622\" stroke-width=\".5\"/><path d=\"M104 32h44\" stroke=\"#9e2f28\" stroke-width=\"1\"/>` +\n    `<text x=\"126\" y=\"${n1(56 + (23 - fs) * .3)}\" text-anchor=\"middle\" class=\"t-name\" style=\"font-size:${fs.toFixed(1)}px\">${name}</text>` +\n    `<text x=\"126\" y=\"72\" text-anchor=\"middle\" class=\"t-sm\">${sp.family} &#183; ${sp.author}</text>` +\n    `<text x=\"14\" y=\"93\" class=\"t-sm\">Loc.</text><text x=\"42\" y=\"93\" class=\"t-hand\">${escapeXML(loc)}</text>` +\n    `<path d=\"M40 96H240\" stroke=\"rgba(74,54,34,.35)\" stroke-width=\".5\" stroke-dasharray=\"1.5 2\"/>` +\n    `<text x=\"14\" y=\"111\" class=\"t-sm\">Coll.</text><text x=\"42\" y=\"111\" class=\"t-hand\">${escapeXML(sp.collector)}</text>` +\n    `<text x=\"240\" y=\"111\" text-anchor=\"end\" class=\"t-hand\">${date}</text>` +\n    `<path d=\"M40 114H240\" stroke=\"rgba(74,54,34,.35)\" stroke-width=\".5\" stroke-dasharray=\"1.5 2\"/>` +\n    `<text x=\"14\" y=\"127\" class=\"t-sm\">No.</text><text x=\"40\" y=\"127\" class=\"t-hand\" style=\"fill:#9e2f28\">${sp.no}</text>` +\n    `<text x=\"240\" y=\"127\" text-anchor=\"end\" class=\"t-sm\" style=\"font-style:italic\">flora incognita</text>` +\n    `</g></g>`;\n}\nfunction stampMarkup(sp, t, R){\n  const rot = R.f(-18, 8);\n  return `<g transform=\"translate(88 776) rotate(${n1(rot)})\"><g class=\"stamp\" style=\"--d:${t.toFixed(2)}s\" opacity=\".62\">` +\n    `<circle r=\"34\" fill=\"none\" stroke=\"#9e2f28\" stroke-width=\"2.2\" stroke-dasharray=\"46 1.5 30 2 60 1\"/>` +\n    `<circle r=\"28.5\" fill=\"none\" stroke=\"#9e2f28\" stroke-width=\".8\"/>` +\n    `<text y=\"-9\" text-anchor=\"middle\" class=\"t-stamp\">HERB.</text>` +\n    `<text y=\"4\" text-anchor=\"middle\" class=\"t-stamp\">IMAG.</text>` +\n    `<path d=\"M-18 9H18\" stroke=\"#9e2f28\" stroke-width=\".7\"/>` +\n    `<text y=\"21\" text-anchor=\"middle\" class=\"t-stamp\" style=\"font-size:8.5px\">CAB. VII</text>` +\n    `</g></g>`;\n}\nfunction scaleMarkup(upc, t){\n  const w = upc; // one centimetre per segment\n  const n = w * 5 > 110 ? 3 : 5;\n  let s = `<g transform=\"translate(142 800)\"><g class=\"ink-late\" style=\"--d:${t.toFixed(2)}s\">`;\n  for (let i = 0; i < n; i++) s += `<rect x=\"${n1(i * w)}\" y=\"0\" width=\"${n1(w)}\" height=\"5\" fill=\"${i % 2 ? '#f9f3e3' : '#4a3622'}\" stroke=\"#4a3622\" stroke-width=\".6\"/>`;\n  s += `<text x=\"0\" y=\"18\" class=\"t-sm\" style=\"font-size:10px\">0</text><text x=\"${n1(n * w)}\" y=\"18\" text-anchor=\"end\" class=\"t-sm\" style=\"font-size:10px\">${n} cm</text></g></g>`;\n  return s;\n}\nfunction packetMarkup(P, t, R){\n  const rot = R.f(-5, 6);\n  let seeds = '';\n  for (let i = 0; i < 5; i++){\n    const x = R.f(-6, 34), y = R.f(78, 96);\n    seeds += `<ellipse cx=\"${n1(x)}\" cy=\"${n1(y)}\" rx=\"3.2\" ry=\"2.1\" transform=\"rotate(${n1(R.f(0, 180))} ${n1(x)} ${n1(y)})\" fill=\"${P.berry}\" stroke=\"rgba(52,30,18,.8)\" stroke-width=\".5\"/>`;\n  }\n  return `<g transform=\"translate(446 60) rotate(${n1(rot)})\"><g class=\"ink-late\" style=\"--d:${t.toFixed(2)}s\">` +\n    `<rect x=\"2\" y=\"3\" width=\"100\" height=\"72\" fill=\"rgba(74,54,34,.12)\"/>` +\n    `<path d=\"M0 0H100V72H0Z\" fill=\"#efe3c6\" stroke=\"#4a3622\" stroke-width=\".8\"/>` +\n    `<path d=\"M0 0L50 30L100 0M0 72L38 40M100 72L62 40\" fill=\"none\" stroke=\"rgba(74,54,34,.45)\" stroke-width=\".6\"/>` +\n    `<text x=\"50\" y=\"60\" text-anchor=\"middle\" class=\"t-hand\" style=\"font-size:13px\">semina</text>` +\n    seeds + `</g></g>`;\n}\nfunction slipMarkup(sp, t, R){\n  const who = R.pick(['E. Ashgrove, 1903', 'P. Hollowbrook, 1911', 'W. Lanternby, 1907', 'O. Marrowby, 1902']);\n  const verdict = R.pick(['surely imaginary', 'nova sp.? — doubtful', 'not as described', 'conf. — with reservations']);\n  const txt = `Det. ${who}: ‘${verdict}’`, w = Math.min(252, txt.length * 5.35 + 18);\n  return `<g transform=\"translate(${n1(570 - w)} 656) rotate(${n1(R.f(-2, 1.5))})\"><g class=\"ink-late\" style=\"--d:${t.toFixed(2)}s\">` +\n    `<rect width=\"${n1(w)}\" height=\"22\" fill=\"#fbf7ea\" stroke=\"rgba(74,54,34,.55)\" stroke-width=\".6\"/>` +\n    `<text x=\"9\" y=\"15\" class=\"t-slip\">${txt}</text></g></g>`;\n}\nfunction escapeXML(s){ return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }\n\n/* ------------------------------------------------------------------\n   Cabinet state and rendering\n------------------------------------------------------------------ */\nconst grid = $('#grid'), indexEl = $('#index');\nconst specimens = [];\nlet collectedCount = 0;\n\nfunction sheetHTML(sp){\n  return `<div class=\"sheet\" style=\"--fox:${sp.fox}\"><svg class=\"plant\" viewBox=\"0 0 600 840\" aria-hidden=\"true\" focusable=\"false\">${sp.plantSVG}</svg><svg class=\"furn\" viewBox=\"0 0 600 840\" aria-hidden=\"true\" focusable=\"false\">${sp.furnSVG}</svg></div>`;\n}\nfunction cardEl(sp, growing){\n  const fig = document.createElement('figure');\n  fig.className = 'card' + (growing && !reduceMotion ? ' grow' : '');\n  fig.setAttribute('role', 'listitem');\n  fig.style.setProperty('--rot', sp.rot.toFixed(2) + 'deg');\n  fig.innerHTML = sheetHTML(sp) +\n    `<figcaption><span class=\"no\">No. ${sp.no}</span><i>${sp.genus} ${sp.epithet}</i></figcaption>` +\n    `<button type=\"button\" class=\"examine\" aria-label=\"Examine specimen number ${sp.no}, ${sp.genus} ${sp.epithet}\"></button>`;\n  fig.querySelector('.examine').addEventListener('click', () => openLightbox(specimens.indexOf(sp)));\n  sp.el = fig;\n  if (growing && !reduceMotion){\n    sp.growTimer = setTimeout(() => fig.classList.remove('grow'), (sp.total + .6) * 1000);\n  }\n  return fig;\n}\nconst WORDS = ['none yet','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve'];\nfunction renderIndex(fresh){\n  indexEl.innerHTML = '';\n  specimens.forEach((sp, i) => {\n    const li = document.createElement('li');\n    if (fresh && i === 0) li.className = 'fresh';\n    li.innerHTML = `<button type=\"button\"><span class=\"ix-no\">${sp.no}</span><i>${sp.genus} ${sp.epithet}</i></button>`;\n    li.querySelector('button').addEventListener('click', () => openLightbox(i));\n    indexEl.appendChild(li);\n  });\n  $('#lg-new').textContent = collectedCount < WORDS.length ? WORDS[collectedCount] : String(collectedCount);\n  const last = specimens.reduce((a, b) => (b.no > a.no ? b : a), specimens[0]);\n  $('#lg-last').textContent = 'No. ' + last.no;\n}\n\nfunction initialDrawer(){\n  const order = HABITS.slice();\n  const r = Math.random;\n  for (let i = order.length - 1; i > 0; i--){ const j = Math.floor(r() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }\n  order.forEach((h) => {\n    const sp = makeSpecimen(h, 'fast');\n    specimens.push(sp);\n  });\n  specimens.forEach((sp, i) => {\n    const el = cardEl(sp, true);\n    el.style.setProperty('--stagger', i);\n    grid.appendChild(el);\n  });\n  renderIndex(false);\n}\n\nlet lastHabit = null;\nfunction collect(){\n  let habit;\n  do { habit = HABITS[Math.floor(Math.random() * HABITS.length)]; } while (habit === lastHabit || habit === (specimens[0] && specimens[0].habit));\n  lastHabit = habit;\n  const firstRects = new Map();\n  specimens.forEach((sp) => firstRects.set(sp, sp.el.getBoundingClientRect()));\n  const sp = makeSpecimen(habit, 'slow');\n  const el = cardEl(sp, true);\n  // the oldest sheet is filed away\n  const old = specimens.length >= 6 ? specimens.pop() : null;\n  if (old){\n    const r = old.el.getBoundingClientRect();\n    const ghost = old.el.cloneNode(true);\n    ghost.classList.remove('grow');\n    Object.assign(ghost.style, { position: 'fixed', left: r.left + 'px', top: r.top + 'px', width: r.width + 'px', margin: '0', zIndex: '5', pointerEvents: 'none' });\n    document.body.appendChild(ghost);\n    old.el.remove();\n    clearTimeout(old.growTimer);\n    if (!reduceMotion){\n      const an = ghost.animate([{ opacity: 1, transform: `rotate(${old.rot}deg)` }, { opacity: 0, transform: `translateY(40px) rotate(${old.rot + 5}deg) scale(.94)` }], { duration: 650, easing: 'cubic-bezier(.4,0,.6,1)' });\n      an.onfinish = () => ghost.remove();\n    } else ghost.remove();\n  }\n  specimens.unshift(sp);\n  grid.prepend(el);\n  collectedCount++;\n  if (!reduceMotion){\n    el.classList.add('enter');\n    setTimeout(() => el.classList.remove('enter'), 900);\n    specimens.slice(1).forEach((s2) => {\n      const a = firstRects.get(s2);\n      if (!a) return;\n      const b = s2.el.getBoundingClientRect();\n      const dx = a.left - b.left, dy = a.top - b.top;\n      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;\n      s2.el.animate([{ transform: `translate(${dx}px,${dy}px) rotate(${s2.rot}deg)` }, { transform: `rotate(${s2.rot}deg)` }], { duration: 620, easing: 'cubic-bezier(.2,.8,.2,1)' });\n    });\n  }\n  renderIndex(true);\n  $('#drawer-note').textContent = `No. ${sp.no} mounted just now`;\n  const rr = el.getBoundingClientRect();\n  if (rr.top < 0 || rr.bottom > window.innerHeight) el.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'center' });\n}\n\n/* pressing */\nconst pressBtn = $('#press'), lbPress = $('#lb-press');\nfunction setPressed(on, animate){\n  document.body.classList.toggle('is-pressed', on);\n  pressBtn.setAttribute('aria-pressed', String(on));\n  lbPress.setAttribute('aria-pressed', String(on));\n  $('#press-label').textContent = on ? 'Release the press' : 'Press the sheets';\n  lbPress.textContent = on ? 'Release' : 'Press';\n  if (animate && !reduceMotion){\n    document.body.classList.remove('pressing');\n    void document.body.offsetWidth;\n    document.body.classList.add('pressing');\n    setTimeout(() => document.body.classList.remove('pressing'), 800);\n  }\n  try { localStorage.setItem('herbarium-pressed', on ? '1' : '0'); } catch (e) { /* storage unavailable */ }\n}\npressBtn.addEventListener('click', () => setPressed(pressBtn.getAttribute('aria-pressed') !== 'true', true));\nlbPress.addEventListener('click', () => setPressed(lbPress.getAttribute('aria-pressed') !== 'true', true));\n$('#collect').addEventListener('click', collect);\n\n/* ------------------------------------------------------------------\n   Lightbox and loupe\n------------------------------------------------------------------ */\nconst lb = $('#lb'), lbSheet = $('#lb-sheet'), loupe = $('#loupe'), loupeView = $('#loupe-view');\nlet lbIndex = -1, lastFocus = null, loupeClone = null;\nconst ZOOM = 2.6;\n\nfunction fillNotes(sp){\n  $('#lb-no').textContent = `Specimen No. ${sp.no}`;\n  $('#lb-title').innerHTML = `<i>${sp.genus} ${sp.epithet}</i> <span class=\"lb-auth\">${sp.author}</span>`;\n  $('#lb-vern').textContent = `“${sp.vern}” — ${sp.family}`;\n  const P = sp.P;\n  const leafWord = { lanceolate: 'lanceolate', ovate: 'ovate', cordate: 'cordate', linear: 'linear', lobed: 'lobed', pinnatifid: 'deeply pinnatifid', orbicular: 'orbicular', spathulate: 'spathulate', oblong: 'oblong pinnules' }[P.leafShape];\n  const margin = P.serr ? 'serrate' : 'entire';\n  const flowers = sp.habit === 'filix' ? 'none — sori beneath the pinnules' :\n    sp.habit === 'umbella' ? `minute, ${P.fcol.name}, in compound umbels` :\n    P.flowerType === 'bell' ? `nodding bells, ${P.fcol.name}` :\n    sp.habit === 'rosula' ? `radiate heads, ${P.fcol.name}` : `${P.petals}-merous, ${P.fcol.name}`;\n  const rows = [\n    ['Habit', HABIT_TEXT[sp.habit]],\n    ['Leaves', sp.habit === 'filix' ? 'fronds pinnate; ' + leafWord : `${leafWord}, ${margin}`],\n    ['Flowers', flowers],\n    ['Height', `c. ${sp.heightCm} cm as mounted`],\n    ['Collected', `${sp.day} ${['March','April','May','June','July','August','September'][sp.month - 3]} ${sp.year}`],\n    ['Locality', sp.locality],\n    ['Collector', sp.collector]\n  ];\n  $('#lb-data').innerHTML = rows.map((r) => `<dt>${r[0]}</dt><dd>${escapeXML(r[1])}</dd>`).join('');\n  $('#lb-desc').textContent = `${sp.whimsy} Grown for this cabinet from seed ${sp.seed.toString(36)}; no second sheet is known.`;\n}\nfunction showInLightbox(i){\n  const sp = specimens[i];\n  if (!sp) return;\n  lbIndex = i;\n  lbSheet.innerHTML = sheetHTML(sp);\n  lbSheet.setAttribute('aria-label', `Enlarged sheet of ${sp.genus} ${sp.epithet}`);\n  fillNotes(sp);\n  buildLoupe();\n}\nfunction buildLoupe(){\n  const sp = specimens[lbIndex];\n  if (!sp) return;\n  loupeView.innerHTML = sheetHTML(sp);\n  loupeClone = loupeView.firstElementChild;\n  sizeLoupe();\n}\nfunction sizeLoupe(){\n  if (!loupeClone) return;\n  const r = lbSheet.getBoundingClientRect();\n  loupeClone.style.width = r.width + 'px';\n  loupeClone.style.height = r.height + 'px';\n}\nfunction openLightbox(i){\n  if (i < 0) return;\n  lastFocus = document.activeElement;\n  lb.hidden = false;\n  document.body.style.overflow = 'hidden';\n  showInLightbox(i);\n  requestAnimationFrame(() => { lb.classList.add('open'); sizeLoupe(); });\n  $('#lb-close').focus({ preventScroll: true });\n}\nfunction closeLightbox(){\n  lb.classList.remove('open');\n  loupe.classList.remove('on');\n  document.body.style.overflow = '';\n  setTimeout(() => { lb.hidden = true; lbSheet.innerHTML = ''; loupeView.innerHTML = ''; loupeClone = null; }, reduceMotion ? 0 : 300);\n  lbIndex = -1;\n  if (lastFocus && lastFocus.focus) lastFocus.focus({ preventScroll: true });\n}\nfunction step(dir){\n  if (lbIndex < 0) return;\n  showInLightbox((lbIndex + dir + specimens.length) % specimens.length);\n}\n$('#lb-close').addEventListener('click', closeLightbox);\n$('#lb-prev').addEventListener('click', () => step(-1));\n$('#lb-next').addEventListener('click', () => step(1));\nlb.addEventListener('click', (e) => { if (e.target === lb) closeLightbox(); });\n\nlet loupeTouchId = null;\nfunction moveLoupe(e){\n  const r = lbSheet.getBoundingClientRect();\n  const px = e.clientX - r.left, py = e.clientY - r.top;\n  if (px < 0 || py < 0 || px > r.width || py > r.height){ loupe.classList.remove('on'); lbSheet.classList.remove('looking'); return; }\n  const lift = e.pointerType === 'touch' ? 130 : 0;\n  loupe.style.translate = `${e.clientX}px ${e.clientY - lift}px`;\n  const R0 = (230 - 16) / 2;\n  loupeView.style.transform = `translate(${R0 - px * ZOOM}px,${R0 - py * ZOOM}px) scale(${ZOOM})`;\n  loupe.classList.add('on');\n  lbSheet.classList.add('looking');\n}\nlbSheet.addEventListener('pointermove', (e) => { if (e.pointerType === 'touch' && loupeTouchId !== e.pointerId) return; moveLoupe(e); });\nlbSheet.addEventListener('pointerdown', (e) => {\n  if (e.pointerType === 'touch'){ loupeTouchId = e.pointerId; try { lbSheet.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ } }\n  moveLoupe(e);\n});\nconst hideLoupe = (e) => {\n  if (e && e.pointerType === 'touch' && e.pointerId !== loupeTouchId) return;\n  loupeTouchId = null;\n  loupe.classList.remove('on'); lbSheet.classList.remove('looking');\n};\nlbSheet.addEventListener('pointerup', (e) => { if (e.pointerType === 'touch') hideLoupe(e); });\nlbSheet.addEventListener('pointercancel', hideLoupe);\nlbSheet.addEventListener('pointerleave', (e) => { if (e.pointerType !== 'touch') hideLoupe(e); });\n\n/* keyboard */\ndocument.addEventListener('keydown', (e) => {\n  if (e.metaKey || e.ctrlKey || e.altKey) return;\n  const open = lbIndex >= 0;\n  if (open){\n    if (e.key === 'Escape'){ e.preventDefault(); closeLightbox(); return; }\n    if (e.key === 'ArrowRight'){ e.preventDefault(); step(1); return; }\n    if (e.key === 'ArrowLeft'){ e.preventDefault(); step(-1); return; }\n    if (e.key === 'Tab'){\n      const f = Array.from(lb.querySelectorAll('button'));\n      const first = f[0], last = f[f.length - 1];\n      if (e.shiftKey && document.activeElement === first){ e.preventDefault(); last.focus(); }\n      else if (!e.shiftKey && document.activeElement === last){ e.preventDefault(); first.focus(); }\n    }\n  }\n  const tag = (document.activeElement && document.activeElement.tagName) || '';\n  if (tag === 'INPUT' || tag === 'TEXTAREA') return;\n  if (e.key === 'n' || e.key === 'N'){ if (!open) collect(); }\n  else if (e.key === 'p' || e.key === 'P'){ setPressed(pressBtn.getAttribute('aria-pressed') !== 'true', true); }\n});\n\nlet rsT = 0;\nwindow.addEventListener('resize', () => { clearTimeout(rsT); rsT = setTimeout(sizeLoupe, 80); });\n\n/* go */\ninitialDrawer();\nlet startPressed = false;\ntry { startPressed = localStorage.getItem('herbarium-pressed') === '1'; } catch (e) { /* storage unavailable */ }\nif (startPressed) setPressed(true, false);\n})();\n</script>\n</body>\n</html>\n";
